window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["dna"]={"id": "dna", "title": "DNA的复制和修复", "sub": "102页教材逐页详解 · 60张概念图 · 41道考题", "sub2": "半保留复制 · DNA聚合酶 · 损伤修复 · 转座", "modules": [{"i": 0, "name": "模块一：半保留复制与复制酶系", "slides": [{"i": 0, "sec": "DNA的复制和修复", "title": "第十章 DNA的复制和修复 (p1)", "notes": "第十章 DNA的复制和修复。\u000b第一节 DNA的复制(DNA指导下DNA的合成)；\u000b第二节 DNA的损伤及修复。\u000b核心：半保留复制→复制机制(复制子/复制叉/酶系)→原核/真核复制→端粒→DNA损伤修复系统。", "page": 1, "level": "掌握", "img": "assets/img/dna/p001.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "DNA的复制和修复", "title": "中心法则总览 (p2)", "notes": "中心法则(Central Dogma)：DNA→复制→DNA；\u000bDNA→转录→RNA→翻译→蛋白质；\u000bRNA→逆转录→DNA。\u000b本章聚焦DNA复制(DNA指导下DNA合成)及DNA损伤修复。", "page": 2, "level": "掌握", "img": "assets/img/dna/p002.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "DNA的复制和修复", "title": "第一节 DNA的复制 (p3)", "notes": "第一节 DNA的复制——DNA指导下DNA的合成。\u000b内容：半保留复制→复制起点/单位→方向性→速度→原核复制分子机制→真核复制→端粒→复制基本特点。", "page": 3, "level": "掌握", "img": "assets/img/dna/p003.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "DNA的复制和修复", "title": "DNA二级结构-Watson-Crick模型 (p4)", "notes": "DNA二级结构(Watson-Crick模型)：反向平行双螺旋；\u000b碱基互补配对(A=T, G≡C)；\u000b两条链方向相反(5'→3'和3'→5')。\u000b互补配对是复制、转录、修复的分子基础。", "page": 4, "level": "掌握", "img": "assets/img/dna/p004.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "DNA的复制和修复", "title": "半保留复制-定义 (p5)", "notes": "一、DNA的半保留复制(Semiconservative replication)。\u000b定义：复制时双链解开，按碱基互补原则，分别以每条单链为模板合成新链。\u000b子代DNA中一条链来自亲代(旧链)，另一条链是新合成的。", "page": 5, "level": "掌握", "img": "assets/img/dna/p005.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "DNA的复制和修复", "title": "Meselson-Stahl实验 (p6)", "notes": "实验证据：1958年Meselson & Stahl用稳定同位素15N示踪法。\u000b大肠杆菌在15NH4Cl中培养12代(全15N)→转入14NH4Cl培养1代→得15N/14N杂交DNA(中间密度)；\u000b培养2代→一半杂交DNA+一半轻DNA(14N)。\u000b结果符合半保留复制(排除全保留/分散复制)。", "page": 6, "level": "掌握", "img": "assets/img/dna/p006.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "DNA的复制和修复", "title": "半保留复制的意义 (p7)", "notes": "意义：①半保留复制是双链DNA普遍的复制机制；\u000b②保持DNA代谢上的稳定性，使遗传物质代代相传(子代忠实保留亲代的一条链)。", "page": 7, "level": "掌握", "img": "assets/img/dna/p007.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "DNA的复制和修复", "title": "复制的起点和单位-复制子 (p8-p9) (p8)", "notes": "二、DNA复制的起点和单位。\u000bDNA从特定位点开始复制(不是随机)，以复制子为单位。\u000b复制子(replicon)：基因组上能独立复制的单位，含复制起点和终点。\u000b原核E.coli：单复制子(4×10^6 bp)；\u000b真核：多复制子(人：约10^3个复制子/染色体，10^5 bp/复制子)。", "page": 8, "level": "掌握", "img": "assets/img/dna/p008.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 8, "sec": "DNA的复制和修复", "title": "大肠杆菌染色体图 (p10)", "notes": "大肠杆菌染色体环状图：显示出DNA代谢相关基因的位置(如dnaA、dnaB、polC等)。\u000b原核环状染色体只有一个复制起点OriC。", "page": 10, "level": "了解", "img": "assets/img/dna/p010.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 9, "sec": "DNA的复制和修复", "title": "复制起点(origin) (p11)", "notes": "复制起点(origin)：DNA分子上100~300bp的多核苷酸片段，具专一核苷酸顺序，可被特异蛋白质识别从而启动复制。\u000b原核染色体：1个复制起点；\u000b真核染色体：多个复制起点。", "page": 11, "level": "掌握", "img": "assets/img/dna/p011.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 10, "sec": "DNA的复制和修复", "title": "大肠杆菌OriC结构 (p12)", "notes": "E.coli复制起点OriC(245bp)：①4个9bp序列(DnaA蛋白结合位点)；\u000b②3个13bp序列(富含AT，在DnaA影响下可解开双链)；\u000b③11个GATC序列(Dam甲基化酶使A甲基化，参与复制调节)。\u000bAT富集区易解链(A=T仅2个氢键)。", "page": 12, "level": "掌握", "img": "assets/img/dna/p012.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 11, "sec": "DNA的复制和修复", "title": "复制眼和复制叉 (p13-p15) (p12)", "notes": "复制眼(replication eye)：复制中的环状染色体产生θ状结构，是正在复制的区域。\u000b复制叉(replication fork)：DNA分子上正在复制的部位，此处亲本双链打开与新合成的DNA单链形成叉状结构(生长点)。", "page": 12, "level": "掌握", "img": "assets/img/dna/p012.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 12, "sec": "DNA的复制和修复", "title": "复制的方向性 (p16-p17) (p13)", "notes": "三、复制的方向性。\u000b双向复制：从一个起点向两侧进行，具两个复制叉(大多数生物)。\u000b单向复制：从一个起点向一侧进行，具一个复制叉(某些原核生物)。\u000b实验：3H-脱氧胸苷标记，双向复制区标记密度高。", "page": 13, "level": "掌握", "img": "assets/img/dna/p013.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 13, "sec": "DNA的复制和修复", "title": "滚动环式和D-环式复制 (p18)", "notes": "特殊复制方式：①滚动环式复制(Rolling circle)：噬菌体φX174(ssDNA)等的复制方式。\u000b②D-环式复制(取代环式)：线粒体DNA、叶绿体DNA的复制方式，由A蛋白介导。", "page": 18, "level": "理解", "img": "assets/img/dna/p018.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 14, "sec": "DNA的复制和修复", "title": "复制的速度 (p19)", "notes": "四、复制的速度。\u000bE.coli：复制叉移动10^5 bp/min，4×10^6 bp DNA约40分钟复制完。\u000b真核生物：复制叉移动1000~3000 bp/min，复制子100~200Kb，30~60分钟。\u000b真核靠多复制子并行弥补速度慢。", "page": 19, "level": "理解", "img": "assets/img/dna/p019.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "dna_mcq_1", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "半保留复制的含义是什么？", "o": ["A. 子代DNA两条链都是新合成的", "B. 子代DNA一条链来自亲代,另一条链新合成", "C. 子代DNA两条链都来自亲代", "D. 复制保留一半RNA"], "a": "B", "e": "半保留复制：每条子代DNA含一条亲代链(模板)+一条新合成链。Meselson-Stahl实验证明。", "kp": "dna_s0_6"}, {"id": "dna_mcq_2", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "Meselson-Stahl实验使用什么方法证明半保留复制？", "o": ["A. 3H标记", "B. 稳定同位素15N示踪+密度梯度离心", "C. 32P标记", "D. 荧光标记"], "a": "B", "e": "15N重氮培养→转14N轻氮→CsCl密度梯度离心，观察15N/14N杂交DNA中间密度带。", "kp": "dna_s0_5"}, {"id": "dna_mcq_3", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "大肠杆菌染色体有几个复制起点？", "o": ["A. 无", "B. 1个(OriC)", "C. 2个", "D. 多个"], "a": "B", "e": "原核环状染色体单复制子单起点OriC；真核多复制子多起点。", "kp": "dna_s0_8"}, {"id": "dna_mcq_4", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "复制子(replicon)的定义是什么？", "o": ["A. 复制的酶", "B. 基因组上能独立复制的单位,含复制起点和终点", "C. RNA引物", "D. 冈崎片段"], "a": "B", "e": "复制子=能独立复制的单位，含起点(可能含终点)。原核单复制子，真核多复制子。", "kp": "dna_s0_7"}, {"id": "dna_mcq_5", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "大肠杆菌OriC中富含AT的13bp序列的作用？", "o": ["A. DnaA结合位点", "B. 在DnaA影响下易解开双链(AT仅2氢键)", "C. Dam甲基化位点", "D. 终止位点"], "a": "B", "e": "3个13bp AT富集序列→A=T仅2个氢键易解链→形成起始解链区。9bp序列是DnaA结合位点。", "kp": "dna_s0_10"}, {"id": "dna_mcq_6", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "复制叉(replication fork)是什么？", "o": ["A. 复制起点", "B. DNA分子上正在复制的部位,亲本双链打开与新链形成叉状", "C. 冈崎片段", "D. 端粒"], "a": "B", "e": "复制叉=生长点，双链解开处与新生链形成Y形叉状结构。", "kp": "dna_s0_11"}, {"id": "dna_mcq_7", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "大多数生物的DNA复制方式是什么？", "o": ["A. 单向复制", "B. 双向复制(两复制叉)", "C. 滚动环式", "D. D环式"], "a": "B", "e": "双向复制：一个起点向两侧进行，具两个复制叉。单向复制见于某些原核生物。", "kp": "dna_s0_0"}, {"id": "dna_mcq_8", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "线粒体DNA和叶绿体DNA的复制方式是什么？", "o": ["A. 半保留双向复制", "B. D环式(取代环式)复制", "C. 滚动环式", "D. 全保留复制"], "a": "B", "e": "D环式复制(取代环式)是线粒体/叶绿体DNA的复制方式。滚动环式见于噬菌体φX174。", "kp": "dna_s0_0"}, {"id": "dna_mcq_9", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "DNA聚合酶催化的链延伸方向是什么？", "o": ["A. 3'→5'", "B. 5'→3'", "C. 双向", "D. 随机"], "a": "B", "e": "DNA聚合酶只能沿5'→3'方向延伸，需模板和引物3'-OH。", "kp": "dna_s0_2"}, {"id": "dna_mcq_10", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "大肠杆菌中真正负责DNA复制合成的酶是哪个？", "o": ["A. PolⅠ", "B. PolⅡ", "C. PolⅢ", "D. PolⅣ"], "a": "C", "e": "PolⅢ是复制主力(DNA复制酶)。PolⅠ切除引物/修复。PolⅡ/Ⅳ/Ⅴ参与修复。", "kp": "dna_s0_8"}], "judge": [], "fill": [{"id": "dna_fill_1", "modI": 0, "q": "DNA复制的方式是________,用________实验证明(15N示踪)。", "a": "半保留复制,Meselson-Stahl", "kp": "dna_s0_12"}, {"id": "dna_fill_12", "modI": 0, "q": "碱基切除修复(BER)中切除异常碱基的酶是________;核苷酸切除修复(NER)中E.coli的切除酶是________。", "a": "DNA糖苷酶,UvrABC(UvrA/UvrB/UvrC)", "kp": "dna_s0_0"}], "short": [{"id": "dna_short_1", "modI": 0, "q": "简述DNA半保留复制及其Meselson-Stahl实验证据。", "a": "【半保留复制定义】\u000b复制时双链解开，按碱基互补原则，以每条单链为模板合成新链。子代DNA一条链来自亲代(旧链)，另一条新合成。\u000b\u000b【Meselson-Stahl实验(1958)】\u000b①大肠杆菌在15NH4Cl(重氮)培养12代→DNA全为15N(重)\u000b②转入14NH4Cl(轻氮)培养1代→离心得单一中间密度带(15N/14N杂交DNA)\u000b③培养2代→得两条带:一条中间密度(15N/14N)+一条轻密度(14N/14N)\u000b\u000b【结论】\u000b实验结果符合半保留复制预测，排除了全保留和分散复制。证明DNA复制是半保留的。", "kp": "dna_s0_5"}, {"id": "dna_short_10", "modI": 0, "q": "简述DNA复制的半保留性、方向性和不连续性。", "a": "【半保留性】\u000b复制时双链解开，以每条单链为模板按碱基互补合成新链，子代DNA保留亲代一条链+新合成一条链。Meselson-Stahl实验证明。\u000b\u000b【方向性】\u000b①DNA新链延伸方向恒为5'→3'(DNA聚合酶只能5'→3')\u000b②复制方向:双向复制(一个起点向两侧,两个复制叉)为主，单向复制为辅\u000b\u000b【不连续性】\u000b①前导链:以3'→5'母链为模板连续合成\u000b②滞后链:以5'→3'母链为模板不连续合成冈崎片段\u000b③两条链合成都是5'→3'，但一条连续一条不连续→半不连续复制\u000b\u000b【根本原因】\u000bDNA双链反向平行+DNA聚合酶只能5'→3'合成→必然导致一条链连续、一条不连续。", "kp": "dna_s0_6"}], "calc": [{"id": "dna_calc_1", "modI": 0, "q": "分析Meselson-Stahl实验的密度梯度离心结果，说明为何能证明半保留复制。", "a": "第一代全为杂交DNA(15N/14N)证明半保留;第二代一半杂交一半轻DNA,排除分散复制", "steps": "实验设计:\u000b①15NH4Cl培养12代→亲代DNA全15N(重)\u000b②转14NH4Cl培养→15N不再掺入\u000b③CsCl密度梯度离心分离不同密度DNA\u000b\u000b【预测各模型的离心结果】\u000b半保留复制:\u000b  F0:1条重带(15N/15N)\u000b  F1:1条中间带(15N/14N杂交)\u000b  F2:1条中间带+1条轻带(14N/14N), 比例1:1\u000b全保留复制:\u000b  F1:1条重带+1条轻带(无中间带)\u000b分散复制:\u000b  F1:1条中间带\u000b  F2:1条中间带(密度逐渐变轻,无双带)\u000b\u000b【实际结果】\u000bF1:单一中间密度带→排除全保留\u000bF2:中间带+轻带两条带→排除分散复制\u000b\u000b【结论】\u000b与半保留复制预测完全一致→DNA复制是半保留的。", "kp": "dna_s0_5"}], "term": [{"id": "dna_term_1", "modI": 0, "term": "半保留复制(Semiconservative Replication)", "def": "①DNA复制时双链解开，按碱基互补原则，以每条单链为模板合成新链的复制方式（定义）。②每个子代DNA分子中一条链来自亲代(旧链)，另一条链是新合成的（特点）。③Meselson-Stahl用15N示踪+密度梯度离心证明（证据）。④意义：是双链DNA普遍的复制机制，保持DNA代谢稳定性，使遗传物质代代相传（意义）。", "kps": "①定义(2分)②一旧一新(1分)③Meselson-Stahl证据(1分)④意义(1分)", "kp": "dna_s0_4"}]}, {"i": 1, "name": "模块二：原核DNA复制机制", "slides": [{"i": 0, "sec": "DNA的复制和修复", "title": "原核复制分子机制总览 (p20)", "notes": "五、原核生物DNA复制的分子机制(以E.coli为例)。\u000b部位：核区。\u000b模板：DNA分子。\u000b引物：单链RNA分子(几个~十几个核苷酸)。\u000b原料：复制用dNTP(dATP/dGTP/dCTP/dTTP)；\u000b合成引物用NTP(rATP/rGTP/rCTP/rUTP)。", "page": 20, "level": "掌握", "img": "assets/img/dna/p020.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "DNA的复制和修复", "title": "DNA聚合酶的特点 (p21-p23) (p2)", "notes": "(一)参与复制的主要酶及蛋白质因子。\u000b1.DNA聚合酶(DNA polymerase)：催化DNA链延长。\u000b特点：①以四种dNTP为底物；\u000b②需模板；\u000b③需引物3'-OH；\u000b④聚合方向5'→3'。\u000b链延伸反应：引物3'-OH对dNTP的α-P亲核攻击，形成磷酸二酯键，释放PPi。", "page": 2, "level": "掌握", "img": "assets/img/dna/p002.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "DNA的复制和修复", "title": "大肠杆菌DNA聚合酶分类 (p24)", "notes": "E.coli DNA聚合酶：PolⅠ、Ⅱ、Ⅲ、Ⅳ、Ⅴ五种。\u000bPolⅢ是复制主力(DNA复制酶)，PolⅠ负责切除引物/修复，PolⅡ/Ⅳ/Ⅴ参与修复。\u000b对比：5'→3'聚合酶活性五种都有；\u000b3'→5'外切酶(校对)活性PolⅠ/Ⅱ/Ⅲ有，PolⅣ/Ⅴ无；\u000b5'→3'外切酶活性仅PolⅠ有。", "page": 24, "level": "掌握", "img": "assets/img/dna/p024.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "DNA的复制和修复", "title": "DNA聚合酶I-Klenow片段 (p25-p26) (p4)", "notes": "PolⅠ结构：被蛋白酶切割成大片段(68kD, Klenow片段)+小片段(35kD)。\u000bKlenow片段含5'→3'聚合酶+3'→5'外切酶(用于基因工程)。\u000b小片段含5'→3'外切酶。\u000bKlenow片段呈右手形结构：指形区(F)、掌形区(P)、拇指区(T)。", "page": 4, "level": "掌握", "img": "assets/img/dna/p004.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "DNA的复制和修复", "title": "Pol I的3'→5'外切酶(校对) (p27)", "notes": "PolⅠ 3'→5'外切酶活性：移去3'末端错配的核苷酸(校对/校读功能)。\u000b合成中若3'末端碱基错配→聚合活性暂停→3'→5'外切酶切除错配碱基→恢复正确碱基→继续聚合。\u000b这是DNA复制高保真的关键。", "page": 27, "level": "掌握", "img": "assets/img/dna/p027.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "DNA的复制和修复", "title": "Pol I的5'→3'外切酶 (p28)", "notes": "PolⅠ 5'→3'外切酶活性：可移去/降解与模板配对的RNA单链或DNA单链(从5'端)。\u000b功能：复制中切除RNA引物；\u000b缺口平移(nick translation)用于标记DNA探针。", "page": 28, "level": "掌握", "img": "assets/img/dna/p028.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "DNA的复制和修复", "title": "DNA聚合酶III (p29-p32) (p7)", "notes": "PolⅢ(DNA复制酶)：核心酶(α、ε、θ亚基)+γ复合物(夹子装载器)+β滑动夹子。\u000b核心酶二聚化。\u000bγ亚基(由dnaX基因部分序列编码)具夹子装载功能，τ亚基具与核心酶/DnaB解旋酶互作的结构域。\u000bβ夹子(β亚基二聚体)环绕DNA，赋予PolⅢ高持续合成能力。", "page": 7, "level": "掌握", "img": "assets/img/dna/p007.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "DNA的复制和修复", "title": "DNA连接酶 (p33)", "notes": "2.DNA连接酶(DNA ligase)：催化双链DNA切口处5'-磷酸基与3'-羟基生成磷酸二酯键。\u000bMr 74000单链肽。\u000b细菌DNA连接酶需NAD+(→NMN++AMP)；\u000b动物/噬菌体需ATP(→AMP+PPi)。\u000b连接冈崎片段、修复缺口。", "page": 33, "level": "掌握", "img": "assets/img/dna/p033.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 8, "sec": "DNA的复制和修复", "title": "DnaA蛋白(起始因子) (p34)", "notes": "3.起始因子DnaA蛋白：20~40个DnaA蛋白识别并结合在DNA复制起始位点(OriC的9bp序列)，以启动复制(需Hu蛋白参与)。\u000bDnaA结合→使邻近13bp AT富集区解链。", "page": 34, "level": "掌握", "img": "assets/img/dna/p034.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 9, "sec": "DNA的复制和修复", "title": "引物合成酶DnaG (p35)", "notes": "4.引物合成酶(primase, DnaG蛋白)：催化合成RNA引物。\u000bDnaG与DnaB蛋白组成引发体(primosome)，参与DNA复制起始阶段。\u000b有些引发体含辅助蛋白(φX174含DnaC、DnaT等)。\u000b引物合成酶不需3'-OH即可从头合成。", "page": 35, "level": "掌握", "img": "assets/img/dna/p035.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 10, "sec": "DNA的复制和修复", "title": "DNA拓扑异构酶 (p36)", "notes": "5.DNA拓扑异构酶(topoisomerase)：拓扑异构酶Ⅰ(ω蛋白)：消除负超螺旋，使复制后DNA恢复正常构象，参与转录(原核)。\u000b拓扑异构酶Ⅱ(旋转酶gyrase)：引入负超螺旋，消除复制叉前进时的扭曲张力，需ATP。\u000b拓扑异构酶Ⅳ：分开环状DNA复制后形成的连锁染色体。", "page": 36, "level": "掌握", "img": "assets/img/dna/p036.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 11, "sec": "DNA的复制和修复", "title": "DNA解螺旋酶DnaB (p37)", "notes": "6.DNA解螺旋酶(helicase, DnaB)：解开DNA双链。\u000b解螺旋酶Ⅰ/Ⅱ/Ⅲ沿模板链5'→3'移动；\u000bRep蛋白沿3'→5'移动(参与修复)；\u000bDnaB沿5'→3'移动(参与复制, Mr 300000由6个亚基组成)。\u000b每解开一对碱基消耗2ATP。", "page": 37, "level": "掌握", "img": "assets/img/dna/p037.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 12, "sec": "DNA的复制和修复", "title": "单链结合蛋白SSB (p38)", "notes": "7.单链结合蛋白(SSB)：Mr 75600，由4个亚基组成。\u000b作用：结合于DNA单链上，防止已分开的单链重新互补配对(维持模板单链状态)，并保护单链不被核酸酶降解。", "page": 38, "level": "掌握", "img": "assets/img/dna/p038.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 13, "sec": "DNA的复制和修复", "title": "复制体(replisome) (p39-p41) (p14)", "notes": "复制体(replisome)：在复制叉(DNA合成生长点)上分布着各种与复制有关的酶和蛋白质因子，它们构成的复合物。\u000b含：旋转酶、解螺旋酶、引物合成酶、PolⅢ(β夹子)、PolⅠ、DNA连接酶、SSB等协同完成复制。", "page": 14, "level": "掌握", "img": "assets/img/dna/p014.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 14, "sec": "DNA的复制和修复", "title": "复制过程总览 (p42-p43) (p15)", "notes": "(二)复制过程。\u000b复制叉处：3'→5'母链为模板连续合成前导链；\u000b5'→3'母链为模板不连续合成滞后链(冈崎片段)。\u000bDNA半不连续复制模型：两条新链合成方向都是5'→3'，但一条连续一条不连续。", "page": 15, "level": "掌握", "img": "assets/img/dna/p015.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "dna_mcq_11", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "DNA聚合酶I的Klenow片段含哪些活性？", "o": ["A. 5'→3'聚合酶+3'→5'外切酶", "B. 5'→3'外切酶", "C. 仅3'→5'外切酶", "D. 仅5'→3'聚合酶"], "a": "A", "e": "Klenow片段(大片段68kD)=5'→3'聚合酶+3'→5'外切酶，用于基因工程。小片段=5'→3'外切酶。", "kp": "dna_s1_3"}, {"id": "dna_mcq_12", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "DNA聚合酶的3'→5'外切酶活性的功能是什么？", "o": ["A. 切除引物", "B. 校对(切除3'末端错配碱基)", "C. 连接片段", "D. 解螺旋"], "a": "B", "e": "3'→5'外切酶=校对功能，及时清除错配碱基，保证复制高保真。", "kp": "dna_s1_2"}, {"id": "dna_mcq_13", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "DNA聚合酶I的5'→3'外切酶活性的功能是什么？", "o": ["A. 校对", "B. 切除RNA引物、缺口平移", "C. 连接DNA", "D. 解螺旋"], "a": "B", "e": "5'→3'外切酶切除引物+缺口平移(标记DNA探针)。仅PolⅠ有。", "kp": "dna_s1_5"}, {"id": "dna_mcq_14", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "DNA连接酶催化什么反应？", "o": ["A. 解螺旋", "B. 催化双链DNA切口处5'-磷酸与3'-羟基生成磷酸二酯键", "C. 合成引物", "D. 切除碱基"], "a": "B", "e": "DNA连接酶连接切口。细菌需NAD+，动物/噬菌体需ATP供能。", "kp": "dna_s1_7"}, {"id": "dna_mcq_15", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "大肠杆菌DNA复制的起始因子(起始蛋白)是？", "o": ["A. DnaB", "B. DnaA", "C. DnaG", "D. SSB"], "a": "B", "e": "DnaA(20-40个)识别结合OriC的9bp序列启动复制。DnaB是解螺旋酶，DnaG是引物合成酶。", "kp": "dna_s1_2"}, {"id": "dna_mcq_16", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "引物合成酶(primase)是哪个蛋白？", "o": ["A. DnaA", "B. DnaB", "C. DnaG", "D. SSB"], "a": "C", "e": "DnaG=引物合成酶，催化合成RNA引物，与DnaB组成引发体。", "kp": "dna_s1_9"}, {"id": "dna_mcq_17", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "拓扑异构酶II(旋转酶gyrase)的功能？", "o": ["A. 消除负超螺旋", "B. 引入负超螺旋,消除复制叉前进的扭曲张力(需ATP)", "C. 解螺旋", "D. 合成引物"], "a": "B", "e": "旋转酶(拓扑异构酶II)引入负超螺旋缓解张力，需ATP。拓扑异构酶I消除负超螺旋。", "kp": "dna_s1_10"}, {"id": "dna_mcq_18", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "参与DNA复制的解螺旋酶是？", "o": ["A. DnaA", "B. DnaB(沿5'→3'移动)", "C. Rep蛋白", "D. SSB"], "a": "B", "e": "DnaB是复制中的解螺旋酶(6亚基,沿5'→3')。Rep蛋白沿3'→5'参与修复。", "kp": "dna_s1_11"}, {"id": "dna_mcq_19", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "单链结合蛋白(SSB)的功能？", "o": ["A. 解螺旋", "B. 结合单链防止重新互补配对", "C. 合成引物", "D. 连接片段"], "a": "B", "e": "SSB(4亚基)结合单链DNA，防止已分开的单链重新配对，并保护单链。", "kp": "dna_s1_12"}, {"id": "dna_mcq_20", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "复制体(replisome)是什么？", "o": ["A. 单个酶", "B. 复制叉上各种酶和蛋白质因子构成的复合物", "C. 引物", "D. 端粒"], "a": "B", "e": "复制体=复制叉上协同工作的酶/蛋白复合物(旋转酶、解螺旋酶、引物酶、PolⅢ、PolⅠ、连接酶等)。", "kp": "dna_s1_13"}], "judge": [], "fill": [{"id": "dna_fill_2", "modI": 1, "q": "大肠杆菌染色体是________复制子,有________个复制起点,其名称是________(245bp)。", "a": "单,1,OriC", "kp": "dna_s1_2"}, {"id": "dna_fill_3", "modI": 1, "q": "DNA聚合酶催化的链延伸方向是________,需要________和________(引物3'-OH)。", "a": "5'→3',模板,引物", "kp": "dna_s1_1"}, {"id": "dna_fill_5", "modI": 1, "q": "大肠杆菌DNA聚合酶Ⅰ含________、________、________三种活性,其大片段称________。", "a": "5'→3'聚合酶,3'→5'外切酶(校对),5'→3'外切酶,Klenow片段", "kp": "dna_s1_2"}, {"id": "dna_fill_6", "modI": 1, "q": "大肠杆菌复制的主要DNA聚合酶是________;引物合成酶是________蛋白;解螺旋酶是________蛋白;起始蛋白是________蛋白。", "a": "PolⅢ,DnaG,DnaB,DnaA", "kp": "dna_s1_2"}], "short": [{"id": "dna_short_2", "modI": 1, "q": "简述原核生物DNA复制的全过程(起始、延伸、终止)。", "a": "【起始】\u000b①Hu蛋白协助下，DnaA(20-40个)识别结合OriC的4个9bp序列→邻近3个13bp AT富集区解链\u000b②DnaC帮助DnaB(六聚体)结合解链区\u000b③DnaB沿5'→3'解螺旋(旋转酶缓解张力,SSB保持单链)\u000b④引物合成酶(DnaG)合成RNA引物\u000b\u000b【延伸】\u000b①PolⅢ以3'→5'母链为模板连续合成前导链\u000b②PolⅢ以5'→3'母链为模板不连续合成冈崎片段(滞后链)\u000b③PolⅠ切除RNA引物并代之以DNA\u000b④DNA连接酶连接相邻片段\u000b\u000b【终止】\u000b①两复制叉在终止区相遇，Tus蛋白结合Ter位点阻止前移\u000b②修复填补终止区50-100bp\u000b③拓扑异构酶Ⅳ分开连锁染色体→两条新DNA分子", "kp": "dna_s1_0"}, {"id": "dna_short_4", "modI": 1, "q": "简述大肠杆菌DNA聚合酶Ⅰ的三种活性及Klenow片段。", "a": "DNA聚合酶Ⅰ含三种酶活性:\u000b\u000b①5'→3'聚合酶活性:催化dNTP加到引物3'-OH，延伸DNA链(需模板+引物)\u000b\u000b②3'→5'外切酶活性(校对):合成中3'末端若错配→暂停聚合→切除错配碱基→恢复正确碱基→继续合成(保证高保真)\u000b\u000b③5'→3'外切酶活性:从5'端切除与模板配对的RNA/DNA单链→用于切除RNA引物、缺口平移\u000b\u000b【Klenow片段】\u000bPolⅠ被蛋白酶切割成大片段(68kD)=Klenow片段，含5'→3'聚合酶+3'→5'外切酶活性。用于基因工程(DNA末端补平、标记探针等)。\u000b小片段(35kD)含5'→3'外切酶活性。\u000b\u000b生理功能:PolⅠ不是复制主力(复制靠PolⅢ)，主要负责切除引物+修复合成。", "kp": "dna_s1_3"}], "calc": [{"id": "dna_calc_2", "modI": 1, "q": "计算大肠杆菌基因组(4×10^6 bp)的复制时间,并说明真核生物如何解决复制速度慢的问题。", "a": "E.coli约40分钟(单复制叉105bp/min双向);真核靠多复制子并行", "steps": "【大肠杆菌】\u000b基因组:4×10^6 bp\u000b复制叉移动速度:10^5 bp/min\u000b双向复制(2个复制叉,但计算按单向推进):\u000b实际上双向复制时,每个复制叉各复制一半:\u000b时间 = 4×10^6 bp ÷ (2 × 10^5 bp/min) = 20分钟\u000b(教材记40分钟,考虑单复制叉推进或起始限制)\u000b\u000b按教材单向计算:4×10^6 ÷ 10^5 = 40分钟\u000b\u000b【真核生物】\u000b复制叉速度慢(1000-3000 bp/min)\u000b但基因组更大(人3×10^9 bp)\u000b单复制子100-200Kb\u000b若单起点:3×10^9 ÷ 2000 = 1.5×10^6 min ≈ 1042天(不可能!)\u000b\u000b【解决方案】\u000b多复制子并行:\u000b人约10^3复制子/染色体, 10^5 bp/复制子\u000b多起点同时启动→总时间仅30-60分钟(每复制子)\u000b\u000b【结论】\u000b真核靠增加复制起点(多复制子)弥补速度慢,而非加快复制叉速度。", "kp": "dna_s1_2"}], "term": [{"id": "dna_term_2", "modI": 1, "term": "复制子(Replicon)", "def": "①基因组上能独立进行复制的单位（定义）。②含有复制的起点，并可能含有复制的终点（组成）。③原核E.coli为单复制子(4×10^6 bp)，真核为多复制子(人约10^3个/染色体)（分布）。④复制以复制子为单位进行（意义）。", "kps": "①定义(2分)②含起点/终点(1分)③原核单/真核多(1分)④意义(1分)", "kp": "dna_s1_13"}, {"id": "dna_term_9", "modI": 1, "term": "Klenow片段", "def": "①大肠杆菌DNA聚合酶Ⅰ被蛋白酶切割产生的大片段(68kD)（定义）。②含5'→3'聚合酶活性和3'→5'外切酶(校对)活性，不含5'→3'外切酶活性（活性）。③小片段(35kD)含5'→3'外切酶活性（对应）。④应用：基因工程中DNA末端补平、标记探针等（应用）。", "kps": "①定义(2分)②两种活性(1分)③小片段(1分)④应用(1分)", "kp": "dna_s1_3"}, {"id": "dna_term_10", "modI": 1, "term": "引物合成酶(Primase/DnaG)", "def": "①催化合成RNA引物的酶（定义）。②不需3'-OH即可从头合成(与DNA聚合酶不同)（特点）。③原核为DnaG蛋白，与DnaB(解螺旋酶)组成引发体(primosome)（组成）。④引物是DNA合成的起始点(提供3'-OH)（功能）。", "kps": "①定义(2分)②不需3'-OH(1分)③引发体(1分)④功能(1分)", "kp": "dna_s1_9"}, {"id": "dna_term_11", "modI": 1, "term": "DNA拓扑异构酶(Topoisomerase)", "def": "①通过切断和重新连接DNA链来改变DNA拓扑状态(超螺旋)的酶（定义）。②拓扑异构酶Ⅰ(ω蛋白)：切断一条链，消除负超螺旋，不需ATP（作用）。③拓扑异构酶Ⅱ(旋转酶gyrase)：切断两条链，引入负超螺旋，消除复制叉前进的扭曲张力，需ATP（作用）。④拓扑异构酶Ⅳ：分开环状DNA复制后形成的连锁染色体（作用）。", "kps": "①定义(2分)②Ⅰ消除负超螺旋(1分)③Ⅱ引入负超螺旋需ATP(1分)④Ⅳ分开连锁染色体(1分)", "kp": "dna_s1_10"}, {"id": "dna_term_12", "modI": 1, "term": "DNA解螺旋酶(Helicase/DnaB)", "def": "①利用ATP水解能量解开DNA双链的酶（定义）。②原核复制中的解螺旋酶为DnaB(6亚基,Mr 300000)，沿模板链5'→3'移动（组成）。③每解开一对碱基消耗2ATP（能耗）。④解螺旋酶Ⅰ/Ⅱ/Ⅲ沿5'→3'，Rep蛋白沿3'→5'(参与修复)（其他）。", "kps": "①定义(2分)②DnaB/5'→3'(1分)③2ATP/碱基对(1分)④其他类型(1分)", "kp": "dna_s1_11"}, {"id": "dna_term_13", "modI": 1, "term": "单链结合蛋白(SSB)", "def": "①结合于DNA单链上、防止单链重新互补配对的蛋白质（定义）。②Mr 75600，由4个亚基组成（结构）。③作用：稳定解开的单链模板状态，保护单链不被核酸酶降解（功能）。④是复制体/修复复合物的重要组成部分（意义）。", "kps": "①定义(2分)②4亚基(1分)③稳定单链/防降解(1分)④意义(1分)", "kp": "dna_s1_12"}, {"id": "dna_term_14", "modI": 1, "term": "复制体(Replisome)", "def": "①在DNA复制叉上分布的各种与复制有关的酶和蛋白质因子构成的复合物（定义）。②组成：旋转酶、解螺旋酶、引物合成酶、PolⅢ(β夹子)、PolⅠ、DNA连接酶、SSB等（组成）。③协同完成DNA双链的解旋、引物合成、链延伸、引物切除和连接（功能）。", "kps": "①定义(2分)②组成(2分)③功能(1分)", "kp": "dna_s1_13"}]}, {"i": 2, "name": "模块三：真核复制与端粒", "slides": [{"i": 0, "sec": "DNA的复制和修复", "title": "半不连续复制 (p44)", "notes": "半不连续复制(semidiscontinuous replication)：新合成的两条子链中，\u000b一条按5'→3'方向连续合成，\u000b称前导链(leading strand)；\u000b另一条不连续，先合成若干短片段(冈崎片段Okazaki fragment)，再由连接酶连接，称滞后链(lagging strand)。", "page": 44, "level": "掌握", "img": "assets/img/dna/p044.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "DNA的复制和修复", "title": "复制的起始 (p45-p46) (p2)", "notes": "复制阶段：起始、延伸、终止。\u000b1.起始：①Hu蛋白协助下，20-40个DnaA识别结合OriC的4个9bp序列→邻近3个13bp AT区解链；\u000b②DnaC帮助DnaB(六聚体)结合解链区；\u000b③DnaB沿5'→3'移动逐步解链(需旋转酶缓解张力，SSB保持单链)；\u000b④引物合成酶合成RNA引物。", "page": 2, "level": "掌握", "img": "assets/img/dna/p002.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "DNA的复制和修复", "title": "复制的延伸 (p47-p50) (p3)", "notes": "2.延伸：①PolⅢ以3'→5'母链为模板连续合成前导链，以5'→3'母链为模板合成冈崎片段；\u000b②PolⅠ从5'→3'切除RNA引物并代之以DNA片段；\u000b③DNA连接酶连接相邻片段。\u000bPolⅢ通过β夹子与模板结合，催化两条链合成。", "page": 3, "level": "掌握", "img": "assets/img/dna/p003.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "DNA的复制和修复", "title": "复制的终止 (p51-p53) (p4)", "notes": "3.终止：①两个复制叉在终止区相遇，Tus蛋白与终止位点(Ter)结合，阻止复制叉前移；\u000b②通过修复方式填补终止区50~100bp未复制区域；\u000b③拓扑异构酶Ⅳ分开连锁染色体，形成两条新DNA双螺旋。", "page": 4, "level": "掌握", "img": "assets/img/dna/p004.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "DNA的复制和修复", "title": "复制的高度准确性 (p54)", "notes": "(三)DNA复制的高度准确性。\u000b①DNA聚合酶的双重核对：底物选择作用+3'→5'外切酶清除错配碱基；\u000b②复制体的复杂结构提高准确性；\u000b③修复系统修正错配和损伤。\u000bE.coli复制引入错误碱基几率仅10^-9~10^-10。", "page": 54, "level": "掌握", "img": "assets/img/dna/p054.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "DNA的复制和修复", "title": "真核生物DNA聚合酶 (p55)", "notes": "六、真核生物DNA的复制。\u000b(一)酶及蛋白质因子。\u000b1.DNA聚合酶：Polα(引物合成)、Polβ(修复)、Polγ(线粒体DNA复制)、Polδ(滞后链)、Polε(前导链)。\u000b3'→5'外切酶(校对)：Polγ/δ/ε有，Polα/β无。\u000bPolδ需PCNA持续合成能力高。", "page": 55, "level": "掌握", "img": "assets/img/dna/p055.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "DNA的复制和修复", "title": "真核生物复制体 (p56-p58) (p7)", "notes": "2.真核复制体组成(与原核对比)：复制酶Polδ(滞后链)/Polε(前导链)(原核PolⅢ)；\u000b进行性因子PCNA(原核β夹子)；\u000b夹子装载器RF-C(原核γ复合物)；\u000b引物合成酶Polα(原核DnaG)；\u000b去除引物RNaseH1+MF-1/FEN1(原核PolⅠ)。\u000bPCNA是三聚体(真核β夹子)。", "page": 7, "level": "掌握", "img": "assets/img/dna/p007.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "DNA的复制和修复", "title": "真核生物复制过程 (p59-p60) (p8)", "notes": "(二)真核复制过程。\u000b与原核相似(半不连续复制)，但更复杂：①需与细胞周期配合(G1期合成S期所需酶)；\u000b②需解决核小体障碍；\u000b③起始更复杂——酵母复制起点ARS(~150bp)形成起点识别复合物(ORC)；\u000bORC+CDC6+CDT1→加载2个MCM2-7解旋酶→前复制复合体(Pre-RC)→加CDC45+GINS→Pre-IC。", "page": 8, "level": "掌握", "img": "assets/img/dna/p008.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 8, "sec": "DNA的复制和修复", "title": "原核与真核复制比较 (p61)", "notes": "原核vs真核复制：复制子(1个 vs 多个)；\u000b起始点(1个 vs 多个)；\u000b延伸速度(10^5 bp/min vs 1000~3000)；\u000b冈崎片段(1000~2000 nt vs 100~200 nt)；\u000b引物(DnaG合成 vs Polα合成RNA引物+起始DNA)；\u000b延伸(PolⅢ异二聚体 vs Polε/Polδ)。", "page": 61, "level": "掌握", "img": "assets/img/dna/p061.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 9, "sec": "DNA的复制和修复", "title": "端粒及复制的困境 (p62-p63) (p10)", "notes": "(三)端粒及端粒的合成。\u000b线性DNA复制的困境：滞后链5'末端RNA引物被切除后无法填补→一条DNA单链的末端每轮复制后缩短。\u000b端粒(telomere)是线性染色体末端的保护结构。", "page": 10, "level": "掌握", "img": "assets/img/dna/p010.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 10, "sec": "DNA的复制和修复", "title": "端粒结构 (p64-p65) (p11)", "notes": "端粒(telomere)：真核线性染色体末端的特殊结构，由许多成串短重复顺序组成，稳定染色体末端。\u000b通式5'(TxGy)n / 3'(AxCy)n。\u000b四膜虫TTGGGG；\u000b拟南芥TTTAGGG；\u000b人TTAGGG。\u000b富G链/富C链。\u000b端粒长度随生长发育改变(大麦)。", "page": 11, "level": "掌握", "img": "assets/img/dna/p011.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 11, "sec": "DNA的复制和修复", "title": "端粒酶 (p66-p67) (p12)", "notes": "2.端粒酶(telomerase)：含RNA链的逆转录酶，以所含RNA为模板合成DNA端粒。\u000b活性：生殖细胞/干细胞有活性；\u000b正常体细胞被抑制；\u000b肿瘤细胞被重新激活(可能参与恶性转化)。\u000b端粒酶蛋白(催化活性)+RNA链(~150碱基，含1.5拷贝端粒重复单位)。", "page": 12, "level": "掌握", "img": "assets/img/dna/p012.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 12, "sec": "DNA的复制和修复", "title": "端粒酶催化机制 (p68-p69) (p13)", "notes": "端粒酶催化端粒DNA合成：①端粒酶结合到端粒3'末端(富G链)，RNA链5'末端识别DNA 3'末端互补配对；\u000b②以RNA为模板延伸富G链；\u000b③合成一个重复单位后前移一个单位；\u000b④端粒DNA 3'突出末端(富G链)延伸；\u000b⑤Polα以RNA为引物合成互补链(富C链)。", "page": 13, "level": "掌握", "img": "assets/img/dna/p013.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 13, "sec": "DNA的复制和修复", "title": "DNA复制的基本特点 (p70-p71) (p14)", "notes": "七、生物体DNA复制的基本特点：①半保留复制；\u000b②起始于特定位置(原核/病毒单复制子单起点，真核多复制子多起点)；\u000b③有单向和双向复制(后者常见)；\u000b④DNA链5'→3'延伸，需RNA引物，半不连续复制。", "page": 14, "level": "掌握", "img": "assets/img/dna/p014.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 14, "sec": "DNA的复制和修复", "title": "第二节 DNA的损伤及修复 (p72)", "notes": "第二节 DNA的损伤及修复。\u000b内容：DNA损伤因素→修复系统(错配修复/切除修复/直接修复/重组修复/倾错修复)→SOS反应。\u000b2015年诺贝尔化学奖授予Tomas Lindahl、Paul Modrich等(修复机制)。", "page": 72, "level": "掌握", "img": "assets/img/dna/p072.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "dna_mcq_21", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "半不连续复制中,前导链的合成特点？", "o": ["A. 不连续合成", "B. 沿5'→3'方向连续合成", "C. 沿3'→5'方向", "D. 不需引物"], "a": "B", "e": "前导链连续合成(模板3'→5')；滞后链不连续合成冈崎片段。", "kp": "dna_s2_0"}, {"id": "dna_mcq_22", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "冈崎片段(Okazaki fragment)是什么？", "o": ["A. 前导链片段", "B. 滞后链上先合成的不连续短片段", "C. RNA引物", "D. 端粒"], "a": "B", "e": "滞后链不连续合成，先合成若干短DNA片段(冈崎片段)，再由连接酶连接。", "kp": "dna_s2_0"}, {"id": "dna_mcq_23", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "DNA复制的三个阶段是什么？", "o": ["A. 解旋、合成、修复", "B. 起始、延伸、终止", "C. 转录、翻译、复制", "D. 识别、结合、切割"], "a": "B", "e": "复制三阶段：起始(DnaA/OriC)、延伸(PolⅢ)、终止(Tus/Ter、拓扑异构酶Ⅳ)。", "kp": "dna_s2_13"}, {"id": "dna_mcq_24", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "大肠杆菌DNA复制引入错误碱基的几率是多少？", "o": ["A. 10^-3", "B. 10^-6", "C. 10^-9~10^-10", "D. 10^-15"], "a": "C", "e": "多重复制保障机制使错误率降至10^-9~10^-10：底物选择+校对+修复系统。", "kp": "dna_s2_13"}, {"id": "dna_mcq_25", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "真核生物中负责前导链合成的DNA聚合酶是？", "o": ["A. Polα", "B. Polδ", "C. Polε", "D. Polγ"], "a": "C", "e": "Polε合成前导链，Polδ合成滞后链，Polα合成引物，Polγ复制线粒体DNA。", "kp": "dna_s2_5"}, {"id": "dna_mcq_26", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "真核生物中相当于原核β夹子的是？", "o": ["A. RF-C", "B. PCNA(增殖细胞抗原)", "C. MCM", "D. FEN1"], "a": "B", "e": "PCNA(三聚体)是真核的滑动夹子(相当于原核β夹子)，赋予Polδ持续合成能力。", "kp": "dna_s2_6"}, {"id": "dna_mcq_27", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "端粒(telomere)的主要功能？", "o": ["A. 编码蛋白", "B. 稳定染色体末端结构,防止末端缩短", "C. 复制起点", "D. 启动子"], "a": "B", "e": "端粒是真核染色体末端重复序列，稳定末端、防止端端融合和末端降解。", "kp": "dna_s2_9"}, {"id": "dna_mcq_28", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "人的端粒重复序列是什么？", "o": ["A. TTGGGG", "B. TTTAGGG", "C. TTAGGG", "D. TTAGGC"], "a": "C", "e": "人端粒重复序列TTAGGG。四膜虫TTGGGG，拟南芥TTTAGGG。", "kp": "dna_s2_11"}, {"id": "dna_mcq_29", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "端粒酶(telomerase)是什么？", "o": ["A. DNA聚合酶", "B. 含RNA链的逆转录酶,以RNA为模板合成端粒DNA", "C. 外切酶", "D. 连接酶"], "a": "B", "e": "端粒酶=逆转录酶+RNA模板，延伸端粒富G链，解决末端复制问题。", "kp": "dna_s2_11"}, {"id": "dna_mcq_30", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "紫外线导致DNA损伤的主要形式？", "o": ["A. 碱基脱氨基", "B. 相邻嘧啶形成嘧啶二聚体(T-T等)", "C. DNA交联", "D. 单链断裂"], "a": "B", "e": "UV使相邻嘧啶(TT/CT/CC)形成环丁烷型嘧啶二聚体，扭曲DNA结构。", "kp": "dna_s2_14"}], "judge": [], "fill": [{"id": "dna_fill_4", "modI": 2, "q": "半不连续复制中,连续合成的链称________,不连续合成的链称________,其中的短片段称________。", "a": "前导链,滞后链,冈崎片段", "kp": "dna_s2_0"}, {"id": "dna_fill_7", "modI": 2, "q": "DNA复制三阶段是________、________、________;终止需________蛋白结合________位点。", "a": "起始,延伸,终止,Tus,Ter", "kp": "dna_s2_13"}, {"id": "dna_fill_8", "modI": 2, "q": "真核生物复制中前导链由Pol________合成,滞后链由Pol________合成,引物由Pol________合成,相当于原核β夹子的是________。", "a": "ε,δ,α,PCNA", "kp": "dna_s2_6"}], "short": [{"id": "dna_short_3", "modI": 2, "q": "比较原核生物与真核生物DNA复制的异同。", "a": "【相同点】\u000b①都是半保留复制、半不连续复制\u000b②链延伸方向5'→3'，需RNA引物\u000b③都有起始/延伸/终止三阶段\u000b\u000b【不同点】\u000b①复制子:原核单复制子 vs 真核多复制子\u000b②起点:原核1个(OriC) vs 真核多个(ARS)\u000b③延伸速度:原核10^5 bp/min vs 真核1000-3000 bp/min\u000b④冈崎片段:原核1000-2000 nt vs 真核100-200 nt\u000b⑤引物合成:原核DnaG vs 真核Polα\u000b⑥复制酶:原核PolⅢ异二聚体 vs 真核Polε(前导)+Polδ(滞后)\u000b⑦进行性因子:原核β夹子 vs 真核PCNA\u000b⑧端粒:真核有端粒酶解决末端问题,原核环状无此问题\u000b⑨真核需与细胞周期配合、需处理核小体", "kp": "dna_s2_5"}, {"id": "dna_short_5", "modI": 2, "q": "简述半不连续复制及前导链、滞后链、冈崎片段。", "a": "【半不连续复制定义】\u000b新合成的两条DNA子链中，一条按5'→3'方向连续合成(前导链)；另一条不连续，先合成若干短片段再由连接酶连接(滞后链)。\u000b\u000b【前导链(leading strand)】\u000b以3'→5'母链为模板，沿5'→3'方向连续合成，只需1个引物。\u000b\u000b【滞后链(lagging strand)】\u000b以5'→3'母链为模板，合成方向与解链方向相反，不连续合成，需多个引物。\u000b\u000b【冈崎片段(Okazaki fragment)】\u000b滞后链上先合成的短DNA片段(原核1000-2000nt,真核100-200nt)。\u000b\u000b【原因】\u000bDNA聚合酶只能5'→3'合成，而两条母链反向平行→一条可连续、另一条必须不连续。\u000b\u000b【过程】\u000bPolⅢ合成冈崎片段→PolⅠ切除引物填补→DNA连接酶连接成完整滞后链。", "kp": "dna_s2_0"}, {"id": "dna_short_6", "modI": 2, "q": "简述端粒酶催化端粒DNA合成的机制及端粒酶的生理意义。", "a": "【端粒酶组成】\u000b端粒酶=蛋白质(逆转录酶催化亚基)+RNA链(~150碱基,含1.5拷贝端粒重复单位作模板)。\u000b\u000b【催化机制】\u000b①端粒酶结合到端粒3'末端(富G链)，RNA链5'末端识别DNA 3'末端并互补配对\u000b②以RNA为模板，端粒酶(逆转录活性)延伸富G链\u000b③合成一个重复单位后，端粒酶前移一个单位\u000b④反复延伸端粒DNA 3'突出末端(富G链)\u000b⑤DNA聚合酶α以RNA为引物合成互补链(富C链)\u000b\u000b【生理意义】\u000b①解决线性DNA末端复制问题(滞后链5'末端引物切除后无法填补)\u000b②维持端粒长度，保护染色体末端\u000b③活性分布:生殖细胞/干细胞有活性;正常体细胞被抑制;肿瘤细胞被重新激活\u000b④端粒长度与细胞衰老、癌症发生密切相关(端粒-端粒酶理论)", "kp": "dna_s2_12"}], "calc": [{"id": "dna_calc_3", "modI": 2, "q": "论述DNA复制的高度准确性(高保真性)的机制。", "a": "多层保障使E.coli复制错误率降至10^-9~10^-10", "steps": "DNA复制的多层保真机制:\u000b\u000b【第一层:底物选择】\u000bDNA聚合酶活性位点对正确碱基(A-T, G-C)有几何/氢键选择性→错误核苷酸难以进入活性中心→初始错误率约10^-5\u000b\u000b【第二层:校对(3'→5'外切酶)】\u000b若错配碱基掺入→聚合酶3'→5'外切酶活性切除错配碱基→正确碱基重新掺入→错误率降至10^-7~10^-8\u000b(注意:PolⅣ/Ⅴ无校对活性→倾错)\u000b\u000b【第三层:错配修复(MMR)】\u000b复制后遗留的错配→MutS识别→切除新链错配区→修复→错误率降至10^-9~10^-10\u000b\u000b【第四层:复制体结构】\u000b复制体的复杂结构(β夹子、双聚合酶)进一步提高准确性\u000b\u000b【第五层:其他修复系统】\u000b切除修复、重组修复等修正各种DNA损伤\u000b\u000b【总结】\u000b底物选择(10^-5)→校对(10^-7)→错配修复(10^-9~10^-10)\u000b三级保障使遗传信息代代忠实传递", "kp": "dna_s2_4"}, {"id": "dna_calc_5", "modI": 2, "q": "论述端粒-端粒酶与细胞衰老和癌症的关系。", "a": "端粒缩短→衰老;端粒酶激活→肿瘤永生", "steps": "【端粒与末端复制问题】\u000b线性DNA滞后链5'末端引物切除后无法填补→每轮复制端粒缩短50-200bp\u000b→端粒是细胞分裂的分子时钟\u000b\u000b【端粒与衰老】\u000b①正常体细胞端粒酶被抑制→端粒随分裂次数缩短\u000b②端粒缩短到临界长度→细胞进入衰老(复制性衰老, Hayflick极限)\u000b③端粒缩短到极短→染色体不稳定→细胞凋亡/癌变\u000b→端粒长度与衰老、寿命相关\u000b\u000b【端粒酶与癌症】\u000b①肿瘤细胞中端粒酶被重新激活(约85-90%肿瘤)\u000b②端粒酶维持端粒长度→细胞逃避衰老→无限增殖(永生化)\u000b③因此端粒酶是癌症治疗的潜在靶点(端粒酶抑制剂)\u000b\u000b【临床应用】\u000b①端粒长度作为衰老/疾病生物标志物\u000b②端粒酶抑制剂:抗癌研究\u000b③端粒酶激活:抗衰老研究(但有致癌风险)\u000b\u000b【总结】\u000b端粒=细胞分裂计数器\u000b正常细胞:端粒缩短→衰老(抑癌保护机制)\u000b癌细胞:端粒酶激活→永生(逃逸机制)\u000b这一矛盾体现了端粒在衰老与癌症中的双面角色", "kp": "dna_s2_11"}], "term": [{"id": "dna_term_3", "modI": 2, "term": "复制起点(Origin)", "def": "①DNA分子上100~300bp的多核苷酸片段，具专一核苷酸顺序，可被特异蛋白质识别从而启动复制的部位（定义）。②原核染色体1个起点(OriC)，真核染色体多个起点（分布）。③E.coli OriC(245bp)含4个9bp序列(DnaA结合位点)、3个13bp序列(AT富集易解链)、11个GATC序列(甲基化)（结构）。④起始蛋白DnaA识别结合启动复制（机制）。", "kps": "①定义(2分)②原核1/真核多(1分)③OriC结构(1分)④DnaA识别(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_4", "modI": 2, "term": "复制叉(Replication Fork)", "def": "①DNA分子上正在进行复制的部位(生长点)（定义）。②此处亲本双链打开，与新合成的DNA单链形成叉状结构（结构）。③复制叉处分布各种酶和蛋白因子，构成复制体（组成）。④双向复制具两个复制叉，单向复制具一个复制叉（类型）。", "kps": "①定义(2分)②叉状结构(1分)③复制体(1分)④双向/单向(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_5", "modI": 2, "term": "冈崎片段(Okazaki Fragment)", "def": "①滞后链合成过程中先合成的不连续短DNA片段（定义）。②因DNA聚合酶只能5'→3'合成，而滞后链模板方向相反，故必须分段合成（成因）。③原核约1000-2000个核苷酸，真核约100-200个核苷酸（大小）。④由PolⅢ合成，PolⅠ切除引物填补，DNA连接酶连接成完整滞后链（过程）。", "kps": "①定义(2分)②成因(1分)③大小(1分)④连接过程(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_6", "modI": 2, "term": "前导链(Leading Strand)", "def": "①DNA复制中以3'→5'母链为模板、沿5'→3'方向连续合成的新链（定义）。②只需一个RNA引物，合成方向与解链方向一致（特点）。③由PolⅢ(原核)或Polε(真核)催化合成（酶）。", "kps": "①定义(2分)②连续合成/单引物(2分)③催化酶(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_7", "modI": 2, "term": "滞后链(Lagging Strand)", "def": "①DNA复制中以5'→3'母链为模板、不连续合成的新链（定义）。②合成方向与解链方向相反，需多个引物，先合成冈崎片段再连接（特点）。③由PolⅢ(原核)或Polδ(真核)催化合成（酶）。④与连续合成的前导链共同构成半不连续复制（联系）。", "kps": "①定义(2分)②不连续/多引物(2分)③催化酶(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_8", "modI": 2, "term": "半不连续复制(Semidiscontinuous Replication)", "def": "①DNA复制中两条新链一条连续合成、一条不连续合成的复制方式（定义）。②前导链连续合成，滞后链先合成冈崎片段再连接（内容）。③根本原因：DNA双链反向平行+DNA聚合酶只能5'→3'合成（原因）。④是生物界DNA复制的普遍方式（意义）。", "kps": "①定义(2分)②前导/滞后(1分)③原因(1分)④普遍性(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_15", "modI": 2, "term": "端粒(Telomere)", "def": "①真核生物线性染色体末端的特殊结构，由许多成串短的重复顺序组成（定义）。②通式5'(TxGy)n/3'(AxCy)n，人端粒重复序列TTAGGG（结构）。③功能：稳定染色体末端结构，防止端端融合和末端降解，解决末端复制问题（功能）。④端粒长度随细胞分裂缩短，与衰老相关（意义）。", "kps": "①定义(2分)②TTAGGG(1分)③功能(1分)④衰老(1分)", "kp": "dna_s2_9"}, {"id": "dna_term_16", "modI": 2, "term": "端粒酶(Telomerase)", "def": "①含RNA链的逆转录酶，以所含RNA为模板合成DNA端粒结构（定义）。②由蛋白质(逆转录酶催化亚基)+RNA链(~150碱基,含1.5拷贝端粒重复单位)组成（组成）。③催化端粒3'末端富G链延伸，解决线性DNA末端复制问题（功能）。④活性：生殖细胞/干细胞有活性，正常体细胞被抑制，肿瘤细胞被重新激活（分布）。", "kps": "①定义(2分)②蛋白+RNA(1分)③功能(1分)④活性分布(1分)", "kp": "dna_s2_11"}, {"id": "dna_term_26", "modI": 2, "term": "PCNA(增殖细胞抗原)", "def": "①真核生物DNA复制的滑动夹子(进行性因子)（定义）。②三聚体结构，相当于原核生物的β夹子（结构）。③功能：环绕DNA，使Polδ/Polε持续合成(提高持续合成能力)（功能）。④由RF-C(夹子装载器)装载到DNA上（装载）。", "kps": "①定义(2分)②三聚体=β夹子(1分)③提高持续合成(1分)④RF-C装载(1分)", "kp": "dna_s2_5"}]}, {"i": 3, "name": "模块四：DNA损伤与修复", "slides": [{"i": 0, "sec": "DNA的复制和修复", "title": "DNA损伤的因素 (p73-p74) (p1)", "notes": "导致DNA损伤的因素：①生物因素(复制错误等)；\u000b②物理因素：紫外线(使相邻嘧啶形成嘧啶二聚体TT/CT/CC)、电离辐射(打断单链/双链、破坏碱基)；\u000b③化学因素：HNO2(碱基脱氨基A→I、C→U造成错配)、烷化剂(碱基错配、交联、脱嘌呤)。", "page": 1, "level": "掌握", "img": "assets/img/dna/p001.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "DNA的复制和修复", "title": "嘧啶二聚体 (p75-p76) (p2)", "notes": "紫外线(UV)导致相邻胸腺嘧啶形成T-T二聚体：相邻嘧啶碱基之间形成环丁烷(cyclobutane)环状结构。\u000b嘧啶二聚体使DNA双螺旋局部扭曲，阻碍复制和转录。\u000b是紫外线致皮肤癌的分子基础。", "page": 2, "level": "掌握", "img": "assets/img/dna/p002.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "DNA的复制和修复", "title": "氮芥引起DNA交联 (p77)", "notes": "氮芥(烷化剂)引起DNA分子两条链在鸟嘌呤上发生交联(crosslink)。\u000bDNA交联阻断复制叉前进，是强致癌剂。\u000b烷化剂作用于G的N7位。", "page": 77, "level": "理解", "img": "assets/img/dna/p077.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "DNA的复制和修复", "title": "修复系统总览 (p78)", "notes": "修复系统分类：①错配修复(mismatch repair)；\u000b②切除修复(excision repair，含碱基切除BER和核苷酸切除NER)；\u000b③直接修复(direct repair)；\u000b④重组修复(recombination repair)；\u000b⑤倾错修复(SOS反应)。", "page": 78, "level": "掌握", "img": "assets/img/dna/p078.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "DNA的复制和修复", "title": "错配修复MMR (p79-p85) (p5)", "notes": "(一)错配修复(MMR)。\u000b定义：复制后短时间内GATC序列呈半甲基化，一旦发现错配碱基，含错配碱基的未甲基化新链被切除，以甲基化链为模板修复。\u000bE.coli中DNA甲基化(GATC序列A的N6)用于区分模板链(甲基化)和新链(未甲基化)。\u000b酶：Dam甲基化酶、MutS(识别错配)、MutL、MutH(核酸内切酶)、外切酶、UvrD、SSB、PolⅢ、连接酶。", "page": 5, "level": "掌握", "img": "assets/img/dna/p005.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "DNA的复制和修复", "title": "直接修复-光复活 (p86-p87) (p6)", "notes": "(二)直接修复：可见光激活光复活酶(photolyase)，\u000b分解紫外线照射形成的嘧啶二聚体，\u000b恢复DNA正常结构(光复活修复photoreactivation repair)。\u000b从低等生物到鸟类皆有，植物中较重要。", "page": 6, "level": "掌握", "img": "assets/img/dna/p006.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "DNA的复制和修复", "title": "切除修复总览 (p88)", "notes": "(三)切除修复(excision repair)：在一系列酶作用下，将DNA中受损部分切除，以完整链为模板合成切去的部分，恢复正常结构。\u000b包括：碱基切除修复(BER)和核苷酸切除修复(NER)。", "page": 88, "level": "掌握", "img": "assets/img/dna/p088.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "DNA的复制和修复", "title": "碱基切除修复BER (p89-p90) (p8)", "notes": "1.碱基切除修复(BER)。\u000b步骤：①DNA糖苷酶断裂N-糖苷键，除去异常碱基→AP位点(无嘌呤/无嘧啶位点)；\u000b②AP核酸内切酶在AP位点附近切开DNA链；\u000b③核酸外切酶切除含AP位点的片段；\u000b④PolⅠ填补空缺；\u000b⑤DNA连接酶连接。\u000b切开→切除→修复→连接。", "page": 8, "level": "掌握", "img": "assets/img/dna/p008.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 8, "sec": "DNA的复制和修复", "title": "核苷酸切除修复NER (p91-p92) (p9)", "notes": "2.核苷酸切除修复(NER)：切除酶在损伤区两侧同时切开，除去含损伤部位的片段。\u000bE.coli ABC切除酶(UvrA/UvrB/UvrC)分别切开损伤部位3'侧第5个、5'侧第8个磷酸二酯键。\u000bPolⅠ填补，连接酶连接。\u000b人细胞也有同源NER系统。", "page": 9, "level": "掌握", "img": "assets/img/dna/p009.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 9, "sec": "DNA的复制和修复", "title": "着色性干皮病 (p93)", "notes": "着色性干皮病(xeroderma pigmentosum, XP)：核苷酸切除修复(NER)系统缺陷导致的遗传病。\u000b患者对紫外线极度敏感→皮肤易发生癌变(皮肤癌)、色素沉着。\u000bXP是NER重要性的经典证据。", "page": 93, "level": "掌握", "img": "assets/img/dna/p093.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 10, "sec": "DNA的复制和修复", "title": "重组修复 (p94-p96) (p11)", "notes": "(四)重组修复(recombination repair)：含嘧啶二聚体等损伤的DNA复制时，子代链在损伤部位出现缺口。\u000b通过遗传重组，从完整母链上将相应片段移至子链缺口。\u000b主要酶：RecA(交换链)、RecBCD(解旋/核酸酶/ATP酶)、RuvABC(分支迁移及重组中间体拆分)、DNA聚合酶和连接酶。", "page": 11, "level": "掌握", "img": "assets/img/dna/p011.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 11, "sec": "DNA的复制和修复", "title": "SOS反应和易错修复 (p97-p98) (p12)", "notes": "(五)应急反应(SOS)和易错修复。\u000bSOS反应：许多可造成DNA损伤或抑制复制的处理能引起一系列复杂的诱导反应。\u000b包括DNA损伤修复、诱变效应、细胞分裂抑制(细胞癌变也相关)。\u000b倾错DNA聚合酶IV、V参与。", "page": 12, "level": "掌握", "img": "assets/img/dna/p012.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 12, "sec": "DNA的复制和修复", "title": "跨损伤DNA合成TLS (p99)", "notes": "跨损伤DNA合成(translesion DNA synthesis,\u000bTLS)：当DNA模板含损伤(如嘧啶二聚体)时，\u000b正常PolⅢ不能越过损伤，\u000b由倾错DNA聚合酶(PolⅣ/Ⅴ)跨过损伤位点继续合成，\u000b代价是可能引入错误(易错修复)。", "page": 99, "level": "理解", "img": "assets/img/dna/p099.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 13, "sec": "DNA的复制和修复", "title": "SOS反应机制 (p100-p101) (p14)", "notes": "3.SOS反应机制(由RecA和LexA阻遏物相互作用引起)：DNA损伤/复制停滞→产生单链DNA(ssDNA)→ssDNA与RecA结合激活RecA*→促进LexA蛋白自身分解→诱导lexA调控子表达(uvrABC、recABCD、ruv、umuDC、dinB、sulA等基因)。", "page": 14, "level": "掌握", "img": "assets/img/dna/p014.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 14, "sec": "DNA的复制和修复", "title": "SOS反应的意义 (p102)", "notes": "4.SOS反应意义：包括两方面——DNA修复(恢复正常结构)和导致变异。\u000b修复使DNA恢复正常；\u000b变异增加物种生存机会，在进化中有重要意义。\u000bSOS是细胞在面临严重损伤时的最后手段(保命优先于保真)。", "page": 102, "level": "掌握", "img": "assets/img/dna/p102.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "dna_mcq_31", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "HNO2(亚硝酸)导致的DNA损伤？", "o": ["A. 形成二聚体", "B. 碱基脱氨基(A→I, C→U)造成错配", "C. 交联", "D. 脱嘌呤"], "a": "B", "e": "HNO2使A脱氨基→次黄嘌呤I(与C配对)、C→U(与A配对)，导致碱基错配。", "kp": "dna_s3_0"}, {"id": "dna_mcq_32", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "错配修复(MMR)中区分模板链和新链的依据？", "o": ["A. 链长度", "B. GATC序列的甲基化(模板链甲基化,新链未甲基化)", "C. 碱基组成", "D. 5'末端"], "a": "B", "e": "Dam甲基化酶使GATC序列A甲基化，复制后新链暂时未甲基化→据此切除新链。", "kp": "dna_s3_4"}, {"id": "dna_mcq_33", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "错配修复中识别错配位点的蛋白是？", "o": ["A. Dam", "B. MutS", "C. MutL", "D. MutH"], "a": "B", "e": "MutS识别错配位点，MutL与MutS结合，MutH是核酸内切酶切开新链。", "kp": "dna_s3_4"}, {"id": "dna_mcq_34", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "光复活修复(直接修复)依赖什么？", "o": ["A. 切除酶", "B. 可见光激活光复活酶分解嘧啶二聚体", "C. 重组酶", "D. DNA聚合酶"], "a": "B", "e": "光复活酶被可见光激活→直接分解嘧啶二聚体→恢复DNA正常结构(直接修复)。", "kp": "dna_s3_5"}, {"id": "dna_mcq_35", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "碱基切除修复(BER)中识别并切除异常碱基的酶是？", "o": ["A. AP核酸内切酶", "B. DNA糖苷酶(断裂N-糖苷键)", "C. DNA聚合酶", "D. 连接酶"], "a": "B", "e": "BER第一步：DNA糖苷酶断裂N-糖苷键除去异常碱基→AP位点→AP核酸内切酶切开。", "kp": "dna_s3_7"}, {"id": "dna_mcq_36", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "着色性干皮病(XP)是哪种修复系统缺陷？", "o": ["A. 错配修复", "B. 核苷酸切除修复(NER)", "C. 碱基切除修复", "D. 重组修复"], "a": "B", "e": "XP=NOR切除修复缺陷→对UV敏感→皮肤癌。是NER重要性的经典证据。", "kp": "dna_s3_9"}, {"id": "dna_mcq_37", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "重组修复中交换链的关键蛋白是？", "o": ["A. RecA", "B. MutS", "C. UvrA", "D. LexA"], "a": "A", "e": "RecA在重组修复中起交换链作用。RecBCD具解旋/核酸酶/ATP酶活性，RuvABC拆分支。", "kp": "dna_s3_10"}, {"id": "dna_mcq_38", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "SOS反应中作为阻遏物被激活的RecA蛋白分解的是？", "o": ["A. MutS", "B. LexA蛋白", "C. Dam", "D. SSB"], "a": "B", "e": "ssDNA+RecA→RecA*→促进LexA自身分解→解除对lexA调控子(修复基因)的抑制→SOS反应。", "kp": "dna_s3_13"}, {"id": "dna_mcq_39", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "倾错DNA聚合酶(跨损伤合成)是哪些？", "o": ["A. PolⅠ和Ⅲ", "B. PolⅣ和Ⅴ", "C. Polα和β", "D. Polδ和ε"], "a": "B", "e": "E.coli倾错聚合酶PolⅣ(dinB)和PolⅤ(umuC/D)可跨过损伤位点合成，但易出错。", "kp": "dna_s3_12"}, {"id": "dna_mcq_40", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "DNA复制中,滞后链的冈崎片段合成后由谁连接？", "o": ["A. 解螺旋酶", "B. DNA连接酶", "C. 引物酶", "D. 拓扑异构酶"], "a": "B", "e": "PolⅠ切除引物填补后，DNA连接酶连接相邻冈崎片段成完整滞后链。", "kp": "dna_s3_12"}, {"id": "dna_mcq_41", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "真核生物复制起始的起点识别复合物是？", "o": ["A. ORC", "B. PCNA", "C. MCM", "D. GINS"], "a": "A", "e": "真核复制起点ARS被ORC(起点识别复合物)识别，ORC+CDC6+CDT1加载MCM2-7解旋酶→Pre-RC。", "kp": "dna_s3_0"}], "judge": [], "fill": [{"id": "dna_fill_9", "modI": 3, "q": "端粒酶是含有________的________酶,以________为模板合成端粒DNA,人的端粒重复序列是________。", "a": "RNA,逆转录,RNA,TTAGGG", "kp": "dna_s3_12"}, {"id": "dna_fill_10", "modI": 3, "q": "紫外线导致DNA损伤的主要形式是________;其修复方式有________(直接修复)和________(切除修复)。", "a": "嘧啶二聚体(T-T),光复活修复,核苷酸切除修复", "kp": "dna_s3_0"}, {"id": "dna_fill_11", "modI": 3, "q": "错配修复中,区分模板链和新链的依据是________序列的________;识别错配的蛋白是________。", "a": "GATC,甲基化,MutS", "kp": "dna_s3_4"}, {"id": "dna_fill_13", "modI": 3, "q": "SOS反应中,ssDNA与________结合激活之,进而促进________蛋白分解,诱导修复基因表达。", "a": "RecA,LexA", "kp": "dna_s3_13"}], "short": [{"id": "dna_short_7", "modI": 3, "q": "简述大肠杆菌错配修复(MMR)的机制。", "a": "【错配修复定义】\u000b复制后DNA在短时间内GATC序列呈半甲基化，一旦发现错配，含错配碱基的未甲基化新链被切除，以甲基化链为模板修复。\u000b\u000b【区分新旧链】\u000bDam甲基化酶使GATC序列A的N6甲基化。复制后新链暂时未甲基化(半甲基化状态)→据此区分模板链(甲基化)和新链(未甲基化)。\u000b\u000b【修复过程】\u000b①MutS二聚体识别新合成链上的错配位点\u000b②MutL与MutS结合→MutL-MutS复合物沿DNA移动至GATC序列\u000b③MutS同时结合错配碱基和GATC→DNA形成突环\u000b④MutH(核酸内切酶)在GATC序列5'端切开新合成单链\u000b⑤核酸外切酶Ⅶ/RecJ(5'→3')或Ⅰ/X(3'→5')切除含错配片段\u000b⑥PolⅢ以甲基化链为模板填补，DNA连接酶连接\u000b\u000b【意义】\u000b消除复制错配，提高复制保真性。", "kp": "dna_s3_4"}, {"id": "dna_short_8", "modI": 3, "q": "简述碱基切除修复(BER)和核苷酸切除修复(NER)的区别。", "a": "【碱基切除修复BER】\u000b修复对象:单个受损/异常碱基(脱氨基、氧化、烷化碱基等)\u000b步骤:\u000b①DNA糖苷酶断裂N-糖苷键→除去异常碱基→形成AP位点(无嘌呤/无嘧啶位点)\u000b②AP核酸内切酶在AP位点附近切开DNA链\u000b③核酸外切酶切除含AP位点的片段\u000b④DNA聚合酶(PolⅠ)填补空缺\u000b⑤DNA连接酶连接\u000b\u000b【核苷酸切除修复NER】\u000b修复对象:引起DNA结构扭曲的大块损伤(嘧啶二聚体、DNA交联等)\u000b步骤:\u000b①切除酶(UvrABC)在损伤区两侧同时切开(3'侧第5个、5'侧第8个磷酸二酯键)\u000b②切除含损伤的寡核苷酸片段\u000b③PolⅠ填补\u000b④连接酶连接\u000b\u000b【区别】\u000b①BER切除单个碱基，NER切除一段核苷酸\u000b②BER由糖苷酶启动，NER由UvrABC切除酶启动\u000b③BER修复小损伤，NER修复结构扭曲的大损伤\u000b④NER缺陷→着色性干皮病(XP)", "kp": "dna_s3_8"}, {"id": "dna_short_9", "modI": 3, "q": "简述SOS反应(应急反应)的机制和意义。", "a": "【SOS反应定义】\u000b许多可造成DNA损伤或抑制复制的处理引起的一系列复杂诱导反应。\u000b\u000b【触发】\u000bDNA损伤/复制停滞→产生单链DNA(ssDNA)\u000b\u000b【机制】\u000b①ssDNA与RecA结合→激活RecA(RecA*)\u000b②RecA*作为辅蛋白酶→促进LexA阻遏蛋白自身分解\u000b③LexA降解→解除对lexA调控子的抑制→诱导uvrABC、recABCD、ruv、umuDC、dinB、sulA等基因表达\u000b④产生的蛋白参与DNA修复(uvrABC切除修复、recA重组修复等)\u000b\u000b【修复方式】\u000b①避免差错修复(error-free):错配修复、直接修复、切除修复、重组修复\u000b②倾向差错修复(error-prone):倾错DNA聚合酶PolⅣ/Ⅴ跨损伤合成(TLS)\u000b\u000b【意义】\u000b①DNA修复使DNA恢复正常结构\u000b②导致变异→增加物种生存机会→进化意义\u000b③细胞面临严重损伤时的最后保命手段(保命优先于保真)\u000b④SOS反应与细胞癌变也有关", "kp": "dna_s3_14"}], "calc": [{"id": "dna_calc_4", "modI": 3, "q": "论述DNA损伤的类型及相应的修复系统。", "a": "损伤类型与修复系统一一对应,构成完整的DNA损伤应答网络", "steps": "【DNA损伤类型】\u000b①碱基错配(复制错误)→错配修复(MMR)\u000b②嘧啶二聚体(UV)→直接修复(光复活酶)/核苷酸切除修复(NER)\u000b③单个异常碱基(脱氨基/氧化/烷化)→碱基切除修复(BER)\u000b④DNA交联(烷化剂)→核苷酸切除修复(NER)\u000b⑤DNA单链/双链断裂(电离辐射)→重组修复\u000b⑥跨损伤DNA合成(TLS)→倾错修复(SOS)\u000b\u000b【修复系统详解】\u000b①错配修复:区分新旧链→切除新链错配→修复\u000b②直接修复:光复活酶分解嘧啶二聚体(不需切除)\u000b③BER:糖苷酶切除异常碱基→AP内切酶→切除→PolⅠ→连接酶\u000b④NER:UvrABC切除损伤片段→PolⅠ→连接酶(XP缺陷)\u000b⑤重组修复:RecA交换链从完整母链补子链缺口\u000b⑥SOS反应:严重损伤时的应急修复(保命优先)\u000b\u000b【意义】\u000bDNA是唯一可被修复的生物大分子(蛋白质/RNA损伤通常直接降解)\u000b修复系统维持基因组稳定性→防止突变→癌症发生与修复缺陷密切相关(XP、Lynch综合征等)", "kp": "dna_s3_0"}], "term": [{"id": "dna_term_17", "modI": 3, "term": "嘧啶二聚体(Pyrimidine Dimer)", "def": "①紫外线照射使DNA同一条链上相邻嘧啶碱基(TT/CT/CC)共价连接形成的二聚体（定义）。②结构：相邻嘧啶间形成环丁烷环状结构（结构）。③危害：使DNA双螺旋局部扭曲，阻碍DNA复制和转录（危害）。④修复：光复活酶直接分解(直接修复)或核苷酸切除修复(NER)（修复）。", "kps": "①定义(2分)②环丁烷结构(1分)③危害(1分)④修复(1分)", "kp": "dna_s3_1"}, {"id": "dna_term_18", "modI": 3, "term": "错配修复(Mismatch Repair, MMR)", "def": "①修复DNA复制后遗留的错配碱基的修复系统（定义）。②原理：复制后短时间内GATC序列半甲基化(模板链甲基化、新链未甲基化)→据此区分新旧链（原理）。③含错配碱基的未甲基化新链被切除，以甲基化链为模板修复（过程）。④关键蛋白：Dam(甲基化)、MutS(识别错配)、MutL、MutH(内切酶)（酶）。", "kps": "①定义(2分)②半甲基化区分新旧链(2分)③MutS等(1分)", "kp": "dna_s3_4"}, {"id": "dna_term_19", "modI": 3, "term": "直接修复(Direct Repair)", "def": "①直接将受损碱基恢复为正常碱基、不需切除的修复方式（定义）。②代表：光复活修复——可见光激活光复活酶分解嘧啶二聚体，恢复DNA正常结构（代表）。③从低等生物到鸟类皆有，植物中较重要（分布）。④与切除修复(需切除受损部分)不同（区别）。", "kps": "①定义(2分)②光复活酶(2分)③与切除修复区别(1分)", "kp": "dna_s3_5"}, {"id": "dna_term_20", "modI": 3, "term": "碱基切除修复(Base-Excision Repair, BER)", "def": "①切除受损的单个碱基、以完整链为模板修复的修复方式（定义）。②步骤：DNA糖苷酶断裂N-糖苷键除去异常碱基→AP位点→AP核酸内切酶切开→外切酶切除→PolⅠ填补→连接酶连接（过程）。③修复对象：单个异常碱基(脱氨基、氧化、烷化碱基等)（对象）。", "kps": "①定义(2分)②DNA糖苷酶+AP内切酶(2分)③修复对象(1分)", "kp": "dna_s3_7"}, {"id": "dna_term_21", "modI": 3, "term": "核苷酸切除修复(Nucleotide-Excision Repair, NER)", "def": "①切除含损伤部位的一段核苷酸、以完整链为模板修复的修复方式（定义）。②E.coli由ABC切除酶(UvrA/UvrB/UvrC)在损伤两侧同时切开(3'侧第5、5'侧第8个磷酸二酯键)，切除片段→PolⅠ填补→连接酶连接（过程）。③修复对象：引起DNA结构扭曲的大块损伤(嘧啶二聚体、交联)（对象）。④缺陷→着色性干皮病(XP)（临床）。", "kps": "①定义(2分)②UvrABC(1分)③修复对象(1分)④XP(1分)", "kp": "dna_s3_8"}, {"id": "dna_term_22", "modI": 3, "term": "着色性干皮病(Xeroderma Pigmentosum, XP)", "def": "①核苷酸切除修复(NER)系统缺陷导致的常染色体隐性遗传病（定义）。②机制：NER缺陷→不能修复紫外线引起的嘧啶二聚体→DNA损伤积累→突变（机制）。③症状：皮肤对紫外线极度敏感、色素沉着、易发皮肤癌（症状）。④意义：XP是证明NER和DNA修复重要性的经典疾病（意义）。", "kps": "①定义(2分)②NER缺陷机制(1分)③症状(1分)④意义(1分)", "kp": "dna_s3_9"}, {"id": "dna_term_23", "modI": 3, "term": "重组修复(Recombination Repair)", "def": "①通过遗传重组从完整母链补充子链缺口的修复方式（定义）。②过程：含嘧啶二聚体等损伤的DNA复制时，子代链在损伤部位出现缺口→RecA交换链从完整母链将相应片段移至子链缺口（过程）。③关键蛋白：RecA(交换链)、RecBCD(解旋/核酸酶/ATP酶)、RuvABC(分支迁移/拆分)（酶）。", "kps": "①定义(2分)②RecA交换链(2分)③RecBCD/RuvABC(1分)", "kp": "dna_s3_10"}, {"id": "dna_term_24", "modI": 3, "term": "SOS反应(SOS Response)", "def": "①许多可造成DNA损伤或抑制复制的处理引起的一系列复杂诱导反应(应急反应)（定义）。②机制：DNA损伤→ssDNA→结合RecA激活RecA*→促进LexA阻遏物自身分解→诱导修复基因(uvrABC/recA/umuDC等)表达（机制）。③包括DNA损伤修复、诱变效应、细胞分裂抑制（内容）。④意义：修复DNA+导致变异(进化意义)，是保命优先的应急修复（意义）。", "kps": "①定义(2分)②RecA-LexA机制(2分)③意义(1分)", "kp": "dna_s3_11"}, {"id": "dna_term_25", "modI": 3, "term": "RecA蛋白", "def": "①参与同源重组和SOS反应的关键蛋白质（定义）。②重组修复中起交换链作用(促进链交换/分支迁移)（重组功能）。③SOS反应中：结合ssDNA→激活RecA*(辅蛋白酶)→促进LexA分解→诱导修复基因（SOS功能）。④是DNA重组和损伤应答的核心蛋白（意义）。", "kps": "①定义(2分)②交换链(1分)③SOS激活LexA分解(1分)④意义(1分)", "kp": "dna_s3_13"}, {"id": "dna_term_27", "modI": 3, "term": "跨损伤DNA合成(Translesion DNA Synthesis, TLS)", "def": "①DNA聚合酶越过模板上损伤位点继续进行DNA合成的过程（定义）。②当模板含嘧啶二聚体等损伤时，正常PolⅢ不能越过→由倾错DNA聚合酶(PolⅣ/Ⅴ)跨过损伤继续合成（机制）。③代价：倾错聚合酶易引入错误→易错修复(error-prone)（特点）。④属于SOS反应诱导的修复系统（归属）。", "kps": "①定义(2分)②PolⅣ/Ⅴ跨损伤(1分)③易错(1分)④属SOS(1分)", "kp": "dna_s3_12"}]}], "mcq": [{"id": "dna_mcq_1", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "半保留复制的含义是什么？", "o": ["A. 子代DNA两条链都是新合成的", "B. 子代DNA一条链来自亲代,另一条链新合成", "C. 子代DNA两条链都来自亲代", "D. 复制保留一半RNA"], "a": "B", "e": "半保留复制：每条子代DNA含一条亲代链(模板)+一条新合成链。Meselson-Stahl实验证明。", "kp": "dna_s0_6"}, {"id": "dna_mcq_2", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "Meselson-Stahl实验使用什么方法证明半保留复制？", "o": ["A. 3H标记", "B. 稳定同位素15N示踪+密度梯度离心", "C. 32P标记", "D. 荧光标记"], "a": "B", "e": "15N重氮培养→转14N轻氮→CsCl密度梯度离心，观察15N/14N杂交DNA中间密度带。", "kp": "dna_s0_5"}, {"id": "dna_mcq_3", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "大肠杆菌染色体有几个复制起点？", "o": ["A. 无", "B. 1个(OriC)", "C. 2个", "D. 多个"], "a": "B", "e": "原核环状染色体单复制子单起点OriC；真核多复制子多起点。", "kp": "dna_s0_8"}, {"id": "dna_mcq_4", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "复制子(replicon)的定义是什么？", "o": ["A. 复制的酶", "B. 基因组上能独立复制的单位,含复制起点和终点", "C. RNA引物", "D. 冈崎片段"], "a": "B", "e": "复制子=能独立复制的单位，含起点(可能含终点)。原核单复制子，真核多复制子。", "kp": "dna_s0_7"}, {"id": "dna_mcq_5", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "大肠杆菌OriC中富含AT的13bp序列的作用？", "o": ["A. DnaA结合位点", "B. 在DnaA影响下易解开双链(AT仅2氢键)", "C. Dam甲基化位点", "D. 终止位点"], "a": "B", "e": "3个13bp AT富集序列→A=T仅2个氢键易解链→形成起始解链区。9bp序列是DnaA结合位点。", "kp": "dna_s0_10"}, {"id": "dna_mcq_6", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "复制叉(replication fork)是什么？", "o": ["A. 复制起点", "B. DNA分子上正在复制的部位,亲本双链打开与新链形成叉状", "C. 冈崎片段", "D. 端粒"], "a": "B", "e": "复制叉=生长点，双链解开处与新生链形成Y形叉状结构。", "kp": "dna_s0_11"}, {"id": "dna_mcq_7", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "大多数生物的DNA复制方式是什么？", "o": ["A. 单向复制", "B. 双向复制(两复制叉)", "C. 滚动环式", "D. D环式"], "a": "B", "e": "双向复制：一个起点向两侧进行，具两个复制叉。单向复制见于某些原核生物。", "kp": "dna_s0_0"}, {"id": "dna_mcq_8", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "线粒体DNA和叶绿体DNA的复制方式是什么？", "o": ["A. 半保留双向复制", "B. D环式(取代环式)复制", "C. 滚动环式", "D. 全保留复制"], "a": "B", "e": "D环式复制(取代环式)是线粒体/叶绿体DNA的复制方式。滚动环式见于噬菌体φX174。", "kp": "dna_s0_0"}, {"id": "dna_mcq_9", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "DNA聚合酶催化的链延伸方向是什么？", "o": ["A. 3'→5'", "B. 5'→3'", "C. 双向", "D. 随机"], "a": "B", "e": "DNA聚合酶只能沿5'→3'方向延伸，需模板和引物3'-OH。", "kp": "dna_s0_2"}, {"id": "dna_mcq_10", "mod": "模块一：半保留复制与复制酶系", "modI": 0, "q": "大肠杆菌中真正负责DNA复制合成的酶是哪个？", "o": ["A. PolⅠ", "B. PolⅡ", "C. PolⅢ", "D. PolⅣ"], "a": "C", "e": "PolⅢ是复制主力(DNA复制酶)。PolⅠ切除引物/修复。PolⅡ/Ⅳ/Ⅴ参与修复。", "kp": "dna_s0_8"}, {"id": "dna_mcq_11", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "DNA聚合酶I的Klenow片段含哪些活性？", "o": ["A. 5'→3'聚合酶+3'→5'外切酶", "B. 5'→3'外切酶", "C. 仅3'→5'外切酶", "D. 仅5'→3'聚合酶"], "a": "A", "e": "Klenow片段(大片段68kD)=5'→3'聚合酶+3'→5'外切酶，用于基因工程。小片段=5'→3'外切酶。", "kp": "dna_s1_3"}, {"id": "dna_mcq_12", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "DNA聚合酶的3'→5'外切酶活性的功能是什么？", "o": ["A. 切除引物", "B. 校对(切除3'末端错配碱基)", "C. 连接片段", "D. 解螺旋"], "a": "B", "e": "3'→5'外切酶=校对功能，及时清除错配碱基，保证复制高保真。", "kp": "dna_s1_2"}, {"id": "dna_mcq_13", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "DNA聚合酶I的5'→3'外切酶活性的功能是什么？", "o": ["A. 校对", "B. 切除RNA引物、缺口平移", "C. 连接DNA", "D. 解螺旋"], "a": "B", "e": "5'→3'外切酶切除引物+缺口平移(标记DNA探针)。仅PolⅠ有。", "kp": "dna_s1_5"}, {"id": "dna_mcq_14", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "DNA连接酶催化什么反应？", "o": ["A. 解螺旋", "B. 催化双链DNA切口处5'-磷酸与3'-羟基生成磷酸二酯键", "C. 合成引物", "D. 切除碱基"], "a": "B", "e": "DNA连接酶连接切口。细菌需NAD+，动物/噬菌体需ATP供能。", "kp": "dna_s1_7"}, {"id": "dna_mcq_15", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "大肠杆菌DNA复制的起始因子(起始蛋白)是？", "o": ["A. DnaB", "B. DnaA", "C. DnaG", "D. SSB"], "a": "B", "e": "DnaA(20-40个)识别结合OriC的9bp序列启动复制。DnaB是解螺旋酶，DnaG是引物合成酶。", "kp": "dna_s1_2"}, {"id": "dna_mcq_16", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "引物合成酶(primase)是哪个蛋白？", "o": ["A. DnaA", "B. DnaB", "C. DnaG", "D. SSB"], "a": "C", "e": "DnaG=引物合成酶，催化合成RNA引物，与DnaB组成引发体。", "kp": "dna_s1_9"}, {"id": "dna_mcq_17", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "拓扑异构酶II(旋转酶gyrase)的功能？", "o": ["A. 消除负超螺旋", "B. 引入负超螺旋,消除复制叉前进的扭曲张力(需ATP)", "C. 解螺旋", "D. 合成引物"], "a": "B", "e": "旋转酶(拓扑异构酶II)引入负超螺旋缓解张力，需ATP。拓扑异构酶I消除负超螺旋。", "kp": "dna_s1_10"}, {"id": "dna_mcq_18", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "参与DNA复制的解螺旋酶是？", "o": ["A. DnaA", "B. DnaB(沿5'→3'移动)", "C. Rep蛋白", "D. SSB"], "a": "B", "e": "DnaB是复制中的解螺旋酶(6亚基,沿5'→3')。Rep蛋白沿3'→5'参与修复。", "kp": "dna_s1_11"}, {"id": "dna_mcq_19", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "单链结合蛋白(SSB)的功能？", "o": ["A. 解螺旋", "B. 结合单链防止重新互补配对", "C. 合成引物", "D. 连接片段"], "a": "B", "e": "SSB(4亚基)结合单链DNA，防止已分开的单链重新配对，并保护单链。", "kp": "dna_s1_12"}, {"id": "dna_mcq_20", "mod": "模块二：原核DNA复制机制", "modI": 1, "q": "复制体(replisome)是什么？", "o": ["A. 单个酶", "B. 复制叉上各种酶和蛋白质因子构成的复合物", "C. 引物", "D. 端粒"], "a": "B", "e": "复制体=复制叉上协同工作的酶/蛋白复合物(旋转酶、解螺旋酶、引物酶、PolⅢ、PolⅠ、连接酶等)。", "kp": "dna_s1_13"}, {"id": "dna_mcq_21", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "半不连续复制中,前导链的合成特点？", "o": ["A. 不连续合成", "B. 沿5'→3'方向连续合成", "C. 沿3'→5'方向", "D. 不需引物"], "a": "B", "e": "前导链连续合成(模板3'→5')；滞后链不连续合成冈崎片段。", "kp": "dna_s2_0"}, {"id": "dna_mcq_22", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "冈崎片段(Okazaki fragment)是什么？", "o": ["A. 前导链片段", "B. 滞后链上先合成的不连续短片段", "C. RNA引物", "D. 端粒"], "a": "B", "e": "滞后链不连续合成，先合成若干短DNA片段(冈崎片段)，再由连接酶连接。", "kp": "dna_s2_0"}, {"id": "dna_mcq_23", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "DNA复制的三个阶段是什么？", "o": ["A. 解旋、合成、修复", "B. 起始、延伸、终止", "C. 转录、翻译、复制", "D. 识别、结合、切割"], "a": "B", "e": "复制三阶段：起始(DnaA/OriC)、延伸(PolⅢ)、终止(Tus/Ter、拓扑异构酶Ⅳ)。", "kp": "dna_s2_13"}, {"id": "dna_mcq_24", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "大肠杆菌DNA复制引入错误碱基的几率是多少？", "o": ["A. 10^-3", "B. 10^-6", "C. 10^-9~10^-10", "D. 10^-15"], "a": "C", "e": "多重复制保障机制使错误率降至10^-9~10^-10：底物选择+校对+修复系统。", "kp": "dna_s2_13"}, {"id": "dna_mcq_25", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "真核生物中负责前导链合成的DNA聚合酶是？", "o": ["A. Polα", "B. Polδ", "C. Polε", "D. Polγ"], "a": "C", "e": "Polε合成前导链，Polδ合成滞后链，Polα合成引物，Polγ复制线粒体DNA。", "kp": "dna_s2_5"}, {"id": "dna_mcq_26", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "真核生物中相当于原核β夹子的是？", "o": ["A. RF-C", "B. PCNA(增殖细胞抗原)", "C. MCM", "D. FEN1"], "a": "B", "e": "PCNA(三聚体)是真核的滑动夹子(相当于原核β夹子)，赋予Polδ持续合成能力。", "kp": "dna_s2_6"}, {"id": "dna_mcq_27", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "端粒(telomere)的主要功能？", "o": ["A. 编码蛋白", "B. 稳定染色体末端结构,防止末端缩短", "C. 复制起点", "D. 启动子"], "a": "B", "e": "端粒是真核染色体末端重复序列，稳定末端、防止端端融合和末端降解。", "kp": "dna_s2_9"}, {"id": "dna_mcq_28", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "人的端粒重复序列是什么？", "o": ["A. TTGGGG", "B. TTTAGGG", "C. TTAGGG", "D. TTAGGC"], "a": "C", "e": "人端粒重复序列TTAGGG。四膜虫TTGGGG，拟南芥TTTAGGG。", "kp": "dna_s2_11"}, {"id": "dna_mcq_29", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "端粒酶(telomerase)是什么？", "o": ["A. DNA聚合酶", "B. 含RNA链的逆转录酶,以RNA为模板合成端粒DNA", "C. 外切酶", "D. 连接酶"], "a": "B", "e": "端粒酶=逆转录酶+RNA模板，延伸端粒富G链，解决末端复制问题。", "kp": "dna_s2_11"}, {"id": "dna_mcq_30", "mod": "模块三：真核复制与端粒", "modI": 2, "q": "紫外线导致DNA损伤的主要形式？", "o": ["A. 碱基脱氨基", "B. 相邻嘧啶形成嘧啶二聚体(T-T等)", "C. DNA交联", "D. 单链断裂"], "a": "B", "e": "UV使相邻嘧啶(TT/CT/CC)形成环丁烷型嘧啶二聚体，扭曲DNA结构。", "kp": "dna_s2_14"}, {"id": "dna_mcq_31", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "HNO2(亚硝酸)导致的DNA损伤？", "o": ["A. 形成二聚体", "B. 碱基脱氨基(A→I, C→U)造成错配", "C. 交联", "D. 脱嘌呤"], "a": "B", "e": "HNO2使A脱氨基→次黄嘌呤I(与C配对)、C→U(与A配对)，导致碱基错配。", "kp": "dna_s3_0"}, {"id": "dna_mcq_32", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "错配修复(MMR)中区分模板链和新链的依据？", "o": ["A. 链长度", "B. GATC序列的甲基化(模板链甲基化,新链未甲基化)", "C. 碱基组成", "D. 5'末端"], "a": "B", "e": "Dam甲基化酶使GATC序列A甲基化，复制后新链暂时未甲基化→据此切除新链。", "kp": "dna_s3_4"}, {"id": "dna_mcq_33", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "错配修复中识别错配位点的蛋白是？", "o": ["A. Dam", "B. MutS", "C. MutL", "D. MutH"], "a": "B", "e": "MutS识别错配位点，MutL与MutS结合，MutH是核酸内切酶切开新链。", "kp": "dna_s3_4"}, {"id": "dna_mcq_34", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "光复活修复(直接修复)依赖什么？", "o": ["A. 切除酶", "B. 可见光激活光复活酶分解嘧啶二聚体", "C. 重组酶", "D. DNA聚合酶"], "a": "B", "e": "光复活酶被可见光激活→直接分解嘧啶二聚体→恢复DNA正常结构(直接修复)。", "kp": "dna_s3_5"}, {"id": "dna_mcq_35", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "碱基切除修复(BER)中识别并切除异常碱基的酶是？", "o": ["A. AP核酸内切酶", "B. DNA糖苷酶(断裂N-糖苷键)", "C. DNA聚合酶", "D. 连接酶"], "a": "B", "e": "BER第一步：DNA糖苷酶断裂N-糖苷键除去异常碱基→AP位点→AP核酸内切酶切开。", "kp": "dna_s3_7"}, {"id": "dna_mcq_36", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "着色性干皮病(XP)是哪种修复系统缺陷？", "o": ["A. 错配修复", "B. 核苷酸切除修复(NER)", "C. 碱基切除修复", "D. 重组修复"], "a": "B", "e": "XP=NOR切除修复缺陷→对UV敏感→皮肤癌。是NER重要性的经典证据。", "kp": "dna_s3_9"}, {"id": "dna_mcq_37", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "重组修复中交换链的关键蛋白是？", "o": ["A. RecA", "B. MutS", "C. UvrA", "D. LexA"], "a": "A", "e": "RecA在重组修复中起交换链作用。RecBCD具解旋/核酸酶/ATP酶活性，RuvABC拆分支。", "kp": "dna_s3_10"}, {"id": "dna_mcq_38", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "SOS反应中作为阻遏物被激活的RecA蛋白分解的是？", "o": ["A. MutS", "B. LexA蛋白", "C. Dam", "D. SSB"], "a": "B", "e": "ssDNA+RecA→RecA*→促进LexA自身分解→解除对lexA调控子(修复基因)的抑制→SOS反应。", "kp": "dna_s3_13"}, {"id": "dna_mcq_39", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "倾错DNA聚合酶(跨损伤合成)是哪些？", "o": ["A. PolⅠ和Ⅲ", "B. PolⅣ和Ⅴ", "C. Polα和β", "D. Polδ和ε"], "a": "B", "e": "E.coli倾错聚合酶PolⅣ(dinB)和PolⅤ(umuC/D)可跨过损伤位点合成，但易出错。", "kp": "dna_s3_12"}, {"id": "dna_mcq_40", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "DNA复制中,滞后链的冈崎片段合成后由谁连接？", "o": ["A. 解螺旋酶", "B. DNA连接酶", "C. 引物酶", "D. 拓扑异构酶"], "a": "B", "e": "PolⅠ切除引物填补后，DNA连接酶连接相邻冈崎片段成完整滞后链。", "kp": "dna_s3_12"}, {"id": "dna_mcq_41", "mod": "模块四：DNA损伤与修复", "modI": 3, "q": "真核生物复制起始的起点识别复合物是？", "o": ["A. ORC", "B. PCNA", "C. MCM", "D. GINS"], "a": "A", "e": "真核复制起点ARS被ORC(起点识别复合物)识别，ORC+CDC6+CDT1加载MCM2-7解旋酶→Pre-RC。", "kp": "dna_s3_0"}], "judge": [], "fill": [{"id": "dna_fill_1", "modI": 0, "q": "DNA复制的方式是________,用________实验证明(15N示踪)。", "a": "半保留复制,Meselson-Stahl", "kp": "dna_s0_12"}, {"id": "dna_fill_2", "modI": 1, "q": "大肠杆菌染色体是________复制子,有________个复制起点,其名称是________(245bp)。", "a": "单,1,OriC", "kp": "dna_s1_2"}, {"id": "dna_fill_3", "modI": 1, "q": "DNA聚合酶催化的链延伸方向是________,需要________和________(引物3'-OH)。", "a": "5'→3',模板,引物", "kp": "dna_s1_1"}, {"id": "dna_fill_4", "modI": 2, "q": "半不连续复制中,连续合成的链称________,不连续合成的链称________,其中的短片段称________。", "a": "前导链,滞后链,冈崎片段", "kp": "dna_s2_0"}, {"id": "dna_fill_5", "modI": 1, "q": "大肠杆菌DNA聚合酶Ⅰ含________、________、________三种活性,其大片段称________。", "a": "5'→3'聚合酶,3'→5'外切酶(校对),5'→3'外切酶,Klenow片段", "kp": "dna_s1_2"}, {"id": "dna_fill_6", "modI": 1, "q": "大肠杆菌复制的主要DNA聚合酶是________;引物合成酶是________蛋白;解螺旋酶是________蛋白;起始蛋白是________蛋白。", "a": "PolⅢ,DnaG,DnaB,DnaA", "kp": "dna_s1_2"}, {"id": "dna_fill_7", "modI": 2, "q": "DNA复制三阶段是________、________、________;终止需________蛋白结合________位点。", "a": "起始,延伸,终止,Tus,Ter", "kp": "dna_s2_13"}, {"id": "dna_fill_8", "modI": 2, "q": "真核生物复制中前导链由Pol________合成,滞后链由Pol________合成,引物由Pol________合成,相当于原核β夹子的是________。", "a": "ε,δ,α,PCNA", "kp": "dna_s2_6"}, {"id": "dna_fill_9", "modI": 3, "q": "端粒酶是含有________的________酶,以________为模板合成端粒DNA,人的端粒重复序列是________。", "a": "RNA,逆转录,RNA,TTAGGG", "kp": "dna_s3_12"}, {"id": "dna_fill_10", "modI": 3, "q": "紫外线导致DNA损伤的主要形式是________;其修复方式有________(直接修复)和________(切除修复)。", "a": "嘧啶二聚体(T-T),光复活修复,核苷酸切除修复", "kp": "dna_s3_0"}, {"id": "dna_fill_11", "modI": 3, "q": "错配修复中,区分模板链和新链的依据是________序列的________;识别错配的蛋白是________。", "a": "GATC,甲基化,MutS", "kp": "dna_s3_4"}, {"id": "dna_fill_12", "modI": 0, "q": "碱基切除修复(BER)中切除异常碱基的酶是________;核苷酸切除修复(NER)中E.coli的切除酶是________。", "a": "DNA糖苷酶,UvrABC(UvrA/UvrB/UvrC)", "kp": "dna_s0_0"}, {"id": "dna_fill_13", "modI": 3, "q": "SOS反应中,ssDNA与________结合激活之,进而促进________蛋白分解,诱导修复基因表达。", "a": "RecA,LexA", "kp": "dna_s3_13"}], "short": [{"id": "dna_short_1", "modI": 0, "q": "简述DNA半保留复制及其Meselson-Stahl实验证据。", "a": "【半保留复制定义】\u000b复制时双链解开，按碱基互补原则，以每条单链为模板合成新链。子代DNA一条链来自亲代(旧链)，另一条新合成。\u000b\u000b【Meselson-Stahl实验(1958)】\u000b①大肠杆菌在15NH4Cl(重氮)培养12代→DNA全为15N(重)\u000b②转入14NH4Cl(轻氮)培养1代→离心得单一中间密度带(15N/14N杂交DNA)\u000b③培养2代→得两条带:一条中间密度(15N/14N)+一条轻密度(14N/14N)\u000b\u000b【结论】\u000b实验结果符合半保留复制预测，排除了全保留和分散复制。证明DNA复制是半保留的。", "kp": "dna_s0_5"}, {"id": "dna_short_2", "modI": 1, "q": "简述原核生物DNA复制的全过程(起始、延伸、终止)。", "a": "【起始】\u000b①Hu蛋白协助下，DnaA(20-40个)识别结合OriC的4个9bp序列→邻近3个13bp AT富集区解链\u000b②DnaC帮助DnaB(六聚体)结合解链区\u000b③DnaB沿5'→3'解螺旋(旋转酶缓解张力,SSB保持单链)\u000b④引物合成酶(DnaG)合成RNA引物\u000b\u000b【延伸】\u000b①PolⅢ以3'→5'母链为模板连续合成前导链\u000b②PolⅢ以5'→3'母链为模板不连续合成冈崎片段(滞后链)\u000b③PolⅠ切除RNA引物并代之以DNA\u000b④DNA连接酶连接相邻片段\u000b\u000b【终止】\u000b①两复制叉在终止区相遇，Tus蛋白结合Ter位点阻止前移\u000b②修复填补终止区50-100bp\u000b③拓扑异构酶Ⅳ分开连锁染色体→两条新DNA分子", "kp": "dna_s1_0"}, {"id": "dna_short_3", "modI": 2, "q": "比较原核生物与真核生物DNA复制的异同。", "a": "【相同点】\u000b①都是半保留复制、半不连续复制\u000b②链延伸方向5'→3'，需RNA引物\u000b③都有起始/延伸/终止三阶段\u000b\u000b【不同点】\u000b①复制子:原核单复制子 vs 真核多复制子\u000b②起点:原核1个(OriC) vs 真核多个(ARS)\u000b③延伸速度:原核10^5 bp/min vs 真核1000-3000 bp/min\u000b④冈崎片段:原核1000-2000 nt vs 真核100-200 nt\u000b⑤引物合成:原核DnaG vs 真核Polα\u000b⑥复制酶:原核PolⅢ异二聚体 vs 真核Polε(前导)+Polδ(滞后)\u000b⑦进行性因子:原核β夹子 vs 真核PCNA\u000b⑧端粒:真核有端粒酶解决末端问题,原核环状无此问题\u000b⑨真核需与细胞周期配合、需处理核小体", "kp": "dna_s2_5"}, {"id": "dna_short_4", "modI": 1, "q": "简述大肠杆菌DNA聚合酶Ⅰ的三种活性及Klenow片段。", "a": "DNA聚合酶Ⅰ含三种酶活性:\u000b\u000b①5'→3'聚合酶活性:催化dNTP加到引物3'-OH，延伸DNA链(需模板+引物)\u000b\u000b②3'→5'外切酶活性(校对):合成中3'末端若错配→暂停聚合→切除错配碱基→恢复正确碱基→继续合成(保证高保真)\u000b\u000b③5'→3'外切酶活性:从5'端切除与模板配对的RNA/DNA单链→用于切除RNA引物、缺口平移\u000b\u000b【Klenow片段】\u000bPolⅠ被蛋白酶切割成大片段(68kD)=Klenow片段，含5'→3'聚合酶+3'→5'外切酶活性。用于基因工程(DNA末端补平、标记探针等)。\u000b小片段(35kD)含5'→3'外切酶活性。\u000b\u000b生理功能:PolⅠ不是复制主力(复制靠PolⅢ)，主要负责切除引物+修复合成。", "kp": "dna_s1_3"}, {"id": "dna_short_5", "modI": 2, "q": "简述半不连续复制及前导链、滞后链、冈崎片段。", "a": "【半不连续复制定义】\u000b新合成的两条DNA子链中，一条按5'→3'方向连续合成(前导链)；另一条不连续，先合成若干短片段再由连接酶连接(滞后链)。\u000b\u000b【前导链(leading strand)】\u000b以3'→5'母链为模板，沿5'→3'方向连续合成，只需1个引物。\u000b\u000b【滞后链(lagging strand)】\u000b以5'→3'母链为模板，合成方向与解链方向相反，不连续合成，需多个引物。\u000b\u000b【冈崎片段(Okazaki fragment)】\u000b滞后链上先合成的短DNA片段(原核1000-2000nt,真核100-200nt)。\u000b\u000b【原因】\u000bDNA聚合酶只能5'→3'合成，而两条母链反向平行→一条可连续、另一条必须不连续。\u000b\u000b【过程】\u000bPolⅢ合成冈崎片段→PolⅠ切除引物填补→DNA连接酶连接成完整滞后链。", "kp": "dna_s2_0"}, {"id": "dna_short_6", "modI": 2, "q": "简述端粒酶催化端粒DNA合成的机制及端粒酶的生理意义。", "a": "【端粒酶组成】\u000b端粒酶=蛋白质(逆转录酶催化亚基)+RNA链(~150碱基,含1.5拷贝端粒重复单位作模板)。\u000b\u000b【催化机制】\u000b①端粒酶结合到端粒3'末端(富G链)，RNA链5'末端识别DNA 3'末端并互补配对\u000b②以RNA为模板，端粒酶(逆转录活性)延伸富G链\u000b③合成一个重复单位后，端粒酶前移一个单位\u000b④反复延伸端粒DNA 3'突出末端(富G链)\u000b⑤DNA聚合酶α以RNA为引物合成互补链(富C链)\u000b\u000b【生理意义】\u000b①解决线性DNA末端复制问题(滞后链5'末端引物切除后无法填补)\u000b②维持端粒长度，保护染色体末端\u000b③活性分布:生殖细胞/干细胞有活性;正常体细胞被抑制;肿瘤细胞被重新激活\u000b④端粒长度与细胞衰老、癌症发生密切相关(端粒-端粒酶理论)", "kp": "dna_s2_12"}, {"id": "dna_short_7", "modI": 3, "q": "简述大肠杆菌错配修复(MMR)的机制。", "a": "【错配修复定义】\u000b复制后DNA在短时间内GATC序列呈半甲基化，一旦发现错配，含错配碱基的未甲基化新链被切除，以甲基化链为模板修复。\u000b\u000b【区分新旧链】\u000bDam甲基化酶使GATC序列A的N6甲基化。复制后新链暂时未甲基化(半甲基化状态)→据此区分模板链(甲基化)和新链(未甲基化)。\u000b\u000b【修复过程】\u000b①MutS二聚体识别新合成链上的错配位点\u000b②MutL与MutS结合→MutL-MutS复合物沿DNA移动至GATC序列\u000b③MutS同时结合错配碱基和GATC→DNA形成突环\u000b④MutH(核酸内切酶)在GATC序列5'端切开新合成单链\u000b⑤核酸外切酶Ⅶ/RecJ(5'→3')或Ⅰ/X(3'→5')切除含错配片段\u000b⑥PolⅢ以甲基化链为模板填补，DNA连接酶连接\u000b\u000b【意义】\u000b消除复制错配，提高复制保真性。", "kp": "dna_s3_4"}, {"id": "dna_short_8", "modI": 3, "q": "简述碱基切除修复(BER)和核苷酸切除修复(NER)的区别。", "a": "【碱基切除修复BER】\u000b修复对象:单个受损/异常碱基(脱氨基、氧化、烷化碱基等)\u000b步骤:\u000b①DNA糖苷酶断裂N-糖苷键→除去异常碱基→形成AP位点(无嘌呤/无嘧啶位点)\u000b②AP核酸内切酶在AP位点附近切开DNA链\u000b③核酸外切酶切除含AP位点的片段\u000b④DNA聚合酶(PolⅠ)填补空缺\u000b⑤DNA连接酶连接\u000b\u000b【核苷酸切除修复NER】\u000b修复对象:引起DNA结构扭曲的大块损伤(嘧啶二聚体、DNA交联等)\u000b步骤:\u000b①切除酶(UvrABC)在损伤区两侧同时切开(3'侧第5个、5'侧第8个磷酸二酯键)\u000b②切除含损伤的寡核苷酸片段\u000b③PolⅠ填补\u000b④连接酶连接\u000b\u000b【区别】\u000b①BER切除单个碱基，NER切除一段核苷酸\u000b②BER由糖苷酶启动，NER由UvrABC切除酶启动\u000b③BER修复小损伤，NER修复结构扭曲的大损伤\u000b④NER缺陷→着色性干皮病(XP)", "kp": "dna_s3_8"}, {"id": "dna_short_9", "modI": 3, "q": "简述SOS反应(应急反应)的机制和意义。", "a": "【SOS反应定义】\u000b许多可造成DNA损伤或抑制复制的处理引起的一系列复杂诱导反应。\u000b\u000b【触发】\u000bDNA损伤/复制停滞→产生单链DNA(ssDNA)\u000b\u000b【机制】\u000b①ssDNA与RecA结合→激活RecA(RecA*)\u000b②RecA*作为辅蛋白酶→促进LexA阻遏蛋白自身分解\u000b③LexA降解→解除对lexA调控子的抑制→诱导uvrABC、recABCD、ruv、umuDC、dinB、sulA等基因表达\u000b④产生的蛋白参与DNA修复(uvrABC切除修复、recA重组修复等)\u000b\u000b【修复方式】\u000b①避免差错修复(error-free):错配修复、直接修复、切除修复、重组修复\u000b②倾向差错修复(error-prone):倾错DNA聚合酶PolⅣ/Ⅴ跨损伤合成(TLS)\u000b\u000b【意义】\u000b①DNA修复使DNA恢复正常结构\u000b②导致变异→增加物种生存机会→进化意义\u000b③细胞面临严重损伤时的最后保命手段(保命优先于保真)\u000b④SOS反应与细胞癌变也有关", "kp": "dna_s3_14"}, {"id": "dna_short_10", "modI": 0, "q": "简述DNA复制的半保留性、方向性和不连续性。", "a": "【半保留性】\u000b复制时双链解开，以每条单链为模板按碱基互补合成新链，子代DNA保留亲代一条链+新合成一条链。Meselson-Stahl实验证明。\u000b\u000b【方向性】\u000b①DNA新链延伸方向恒为5'→3'(DNA聚合酶只能5'→3')\u000b②复制方向:双向复制(一个起点向两侧,两个复制叉)为主，单向复制为辅\u000b\u000b【不连续性】\u000b①前导链:以3'→5'母链为模板连续合成\u000b②滞后链:以5'→3'母链为模板不连续合成冈崎片段\u000b③两条链合成都是5'→3'，但一条连续一条不连续→半不连续复制\u000b\u000b【根本原因】\u000bDNA双链反向平行+DNA聚合酶只能5'→3'合成→必然导致一条链连续、一条不连续。", "kp": "dna_s0_6"}], "calc": [{"id": "dna_calc_1", "modI": 0, "q": "分析Meselson-Stahl实验的密度梯度离心结果，说明为何能证明半保留复制。", "a": "第一代全为杂交DNA(15N/14N)证明半保留;第二代一半杂交一半轻DNA,排除分散复制", "steps": "实验设计:\u000b①15NH4Cl培养12代→亲代DNA全15N(重)\u000b②转14NH4Cl培养→15N不再掺入\u000b③CsCl密度梯度离心分离不同密度DNA\u000b\u000b【预测各模型的离心结果】\u000b半保留复制:\u000b  F0:1条重带(15N/15N)\u000b  F1:1条中间带(15N/14N杂交)\u000b  F2:1条中间带+1条轻带(14N/14N), 比例1:1\u000b全保留复制:\u000b  F1:1条重带+1条轻带(无中间带)\u000b分散复制:\u000b  F1:1条中间带\u000b  F2:1条中间带(密度逐渐变轻,无双带)\u000b\u000b【实际结果】\u000bF1:单一中间密度带→排除全保留\u000bF2:中间带+轻带两条带→排除分散复制\u000b\u000b【结论】\u000b与半保留复制预测完全一致→DNA复制是半保留的。", "kp": "dna_s0_5"}, {"id": "dna_calc_2", "modI": 1, "q": "计算大肠杆菌基因组(4×10^6 bp)的复制时间,并说明真核生物如何解决复制速度慢的问题。", "a": "E.coli约40分钟(单复制叉105bp/min双向);真核靠多复制子并行", "steps": "【大肠杆菌】\u000b基因组:4×10^6 bp\u000b复制叉移动速度:10^5 bp/min\u000b双向复制(2个复制叉,但计算按单向推进):\u000b实际上双向复制时,每个复制叉各复制一半:\u000b时间 = 4×10^6 bp ÷ (2 × 10^5 bp/min) = 20分钟\u000b(教材记40分钟,考虑单复制叉推进或起始限制)\u000b\u000b按教材单向计算:4×10^6 ÷ 10^5 = 40分钟\u000b\u000b【真核生物】\u000b复制叉速度慢(1000-3000 bp/min)\u000b但基因组更大(人3×10^9 bp)\u000b单复制子100-200Kb\u000b若单起点:3×10^9 ÷ 2000 = 1.5×10^6 min ≈ 1042天(不可能!)\u000b\u000b【解决方案】\u000b多复制子并行:\u000b人约10^3复制子/染色体, 10^5 bp/复制子\u000b多起点同时启动→总时间仅30-60分钟(每复制子)\u000b\u000b【结论】\u000b真核靠增加复制起点(多复制子)弥补速度慢,而非加快复制叉速度。", "kp": "dna_s1_2"}, {"id": "dna_calc_3", "modI": 2, "q": "论述DNA复制的高度准确性(高保真性)的机制。", "a": "多层保障使E.coli复制错误率降至10^-9~10^-10", "steps": "DNA复制的多层保真机制:\u000b\u000b【第一层:底物选择】\u000bDNA聚合酶活性位点对正确碱基(A-T, G-C)有几何/氢键选择性→错误核苷酸难以进入活性中心→初始错误率约10^-5\u000b\u000b【第二层:校对(3'→5'外切酶)】\u000b若错配碱基掺入→聚合酶3'→5'外切酶活性切除错配碱基→正确碱基重新掺入→错误率降至10^-7~10^-8\u000b(注意:PolⅣ/Ⅴ无校对活性→倾错)\u000b\u000b【第三层:错配修复(MMR)】\u000b复制后遗留的错配→MutS识别→切除新链错配区→修复→错误率降至10^-9~10^-10\u000b\u000b【第四层:复制体结构】\u000b复制体的复杂结构(β夹子、双聚合酶)进一步提高准确性\u000b\u000b【第五层:其他修复系统】\u000b切除修复、重组修复等修正各种DNA损伤\u000b\u000b【总结】\u000b底物选择(10^-5)→校对(10^-7)→错配修复(10^-9~10^-10)\u000b三级保障使遗传信息代代忠实传递", "kp": "dna_s2_4"}, {"id": "dna_calc_4", "modI": 3, "q": "论述DNA损伤的类型及相应的修复系统。", "a": "损伤类型与修复系统一一对应,构成完整的DNA损伤应答网络", "steps": "【DNA损伤类型】\u000b①碱基错配(复制错误)→错配修复(MMR)\u000b②嘧啶二聚体(UV)→直接修复(光复活酶)/核苷酸切除修复(NER)\u000b③单个异常碱基(脱氨基/氧化/烷化)→碱基切除修复(BER)\u000b④DNA交联(烷化剂)→核苷酸切除修复(NER)\u000b⑤DNA单链/双链断裂(电离辐射)→重组修复\u000b⑥跨损伤DNA合成(TLS)→倾错修复(SOS)\u000b\u000b【修复系统详解】\u000b①错配修复:区分新旧链→切除新链错配→修复\u000b②直接修复:光复活酶分解嘧啶二聚体(不需切除)\u000b③BER:糖苷酶切除异常碱基→AP内切酶→切除→PolⅠ→连接酶\u000b④NER:UvrABC切除损伤片段→PolⅠ→连接酶(XP缺陷)\u000b⑤重组修复:RecA交换链从完整母链补子链缺口\u000b⑥SOS反应:严重损伤时的应急修复(保命优先)\u000b\u000b【意义】\u000bDNA是唯一可被修复的生物大分子(蛋白质/RNA损伤通常直接降解)\u000b修复系统维持基因组稳定性→防止突变→癌症发生与修复缺陷密切相关(XP、Lynch综合征等)", "kp": "dna_s3_0"}, {"id": "dna_calc_5", "modI": 2, "q": "论述端粒-端粒酶与细胞衰老和癌症的关系。", "a": "端粒缩短→衰老;端粒酶激活→肿瘤永生", "steps": "【端粒与末端复制问题】\u000b线性DNA滞后链5'末端引物切除后无法填补→每轮复制端粒缩短50-200bp\u000b→端粒是细胞分裂的分子时钟\u000b\u000b【端粒与衰老】\u000b①正常体细胞端粒酶被抑制→端粒随分裂次数缩短\u000b②端粒缩短到临界长度→细胞进入衰老(复制性衰老, Hayflick极限)\u000b③端粒缩短到极短→染色体不稳定→细胞凋亡/癌变\u000b→端粒长度与衰老、寿命相关\u000b\u000b【端粒酶与癌症】\u000b①肿瘤细胞中端粒酶被重新激活(约85-90%肿瘤)\u000b②端粒酶维持端粒长度→细胞逃避衰老→无限增殖(永生化)\u000b③因此端粒酶是癌症治疗的潜在靶点(端粒酶抑制剂)\u000b\u000b【临床应用】\u000b①端粒长度作为衰老/疾病生物标志物\u000b②端粒酶抑制剂:抗癌研究\u000b③端粒酶激活:抗衰老研究(但有致癌风险)\u000b\u000b【总结】\u000b端粒=细胞分裂计数器\u000b正常细胞:端粒缩短→衰老(抑癌保护机制)\u000b癌细胞:端粒酶激活→永生(逃逸机制)\u000b这一矛盾体现了端粒在衰老与癌症中的双面角色", "kp": "dna_s2_11"}], "term": [{"id": "dna_term_1", "modI": 0, "term": "半保留复制(Semiconservative Replication)", "def": "①DNA复制时双链解开，按碱基互补原则，以每条单链为模板合成新链的复制方式（定义）。②每个子代DNA分子中一条链来自亲代(旧链)，另一条链是新合成的（特点）。③Meselson-Stahl用15N示踪+密度梯度离心证明（证据）。④意义：是双链DNA普遍的复制机制，保持DNA代谢稳定性，使遗传物质代代相传（意义）。", "kps": "①定义(2分)②一旧一新(1分)③Meselson-Stahl证据(1分)④意义(1分)", "kp": "dna_s0_4"}, {"id": "dna_term_2", "modI": 1, "term": "复制子(Replicon)", "def": "①基因组上能独立进行复制的单位（定义）。②含有复制的起点，并可能含有复制的终点（组成）。③原核E.coli为单复制子(4×10^6 bp)，真核为多复制子(人约10^3个/染色体)（分布）。④复制以复制子为单位进行（意义）。", "kps": "①定义(2分)②含起点/终点(1分)③原核单/真核多(1分)④意义(1分)", "kp": "dna_s1_13"}, {"id": "dna_term_3", "modI": 2, "term": "复制起点(Origin)", "def": "①DNA分子上100~300bp的多核苷酸片段，具专一核苷酸顺序，可被特异蛋白质识别从而启动复制的部位（定义）。②原核染色体1个起点(OriC)，真核染色体多个起点（分布）。③E.coli OriC(245bp)含4个9bp序列(DnaA结合位点)、3个13bp序列(AT富集易解链)、11个GATC序列(甲基化)（结构）。④起始蛋白DnaA识别结合启动复制（机制）。", "kps": "①定义(2分)②原核1/真核多(1分)③OriC结构(1分)④DnaA识别(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_4", "modI": 2, "term": "复制叉(Replication Fork)", "def": "①DNA分子上正在进行复制的部位(生长点)（定义）。②此处亲本双链打开，与新合成的DNA单链形成叉状结构（结构）。③复制叉处分布各种酶和蛋白因子，构成复制体（组成）。④双向复制具两个复制叉，单向复制具一个复制叉（类型）。", "kps": "①定义(2分)②叉状结构(1分)③复制体(1分)④双向/单向(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_5", "modI": 2, "term": "冈崎片段(Okazaki Fragment)", "def": "①滞后链合成过程中先合成的不连续短DNA片段（定义）。②因DNA聚合酶只能5'→3'合成，而滞后链模板方向相反，故必须分段合成（成因）。③原核约1000-2000个核苷酸，真核约100-200个核苷酸（大小）。④由PolⅢ合成，PolⅠ切除引物填补，DNA连接酶连接成完整滞后链（过程）。", "kps": "①定义(2分)②成因(1分)③大小(1分)④连接过程(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_6", "modI": 2, "term": "前导链(Leading Strand)", "def": "①DNA复制中以3'→5'母链为模板、沿5'→3'方向连续合成的新链（定义）。②只需一个RNA引物，合成方向与解链方向一致（特点）。③由PolⅢ(原核)或Polε(真核)催化合成（酶）。", "kps": "①定义(2分)②连续合成/单引物(2分)③催化酶(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_7", "modI": 2, "term": "滞后链(Lagging Strand)", "def": "①DNA复制中以5'→3'母链为模板、不连续合成的新链（定义）。②合成方向与解链方向相反，需多个引物，先合成冈崎片段再连接（特点）。③由PolⅢ(原核)或Polδ(真核)催化合成（酶）。④与连续合成的前导链共同构成半不连续复制（联系）。", "kps": "①定义(2分)②不连续/多引物(2分)③催化酶(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_8", "modI": 2, "term": "半不连续复制(Semidiscontinuous Replication)", "def": "①DNA复制中两条新链一条连续合成、一条不连续合成的复制方式（定义）。②前导链连续合成，滞后链先合成冈崎片段再连接（内容）。③根本原因：DNA双链反向平行+DNA聚合酶只能5'→3'合成（原因）。④是生物界DNA复制的普遍方式（意义）。", "kps": "①定义(2分)②前导/滞后(1分)③原因(1分)④普遍性(1分)", "kp": "dna_s2_0"}, {"id": "dna_term_9", "modI": 1, "term": "Klenow片段", "def": "①大肠杆菌DNA聚合酶Ⅰ被蛋白酶切割产生的大片段(68kD)（定义）。②含5'→3'聚合酶活性和3'→5'外切酶(校对)活性，不含5'→3'外切酶活性（活性）。③小片段(35kD)含5'→3'外切酶活性（对应）。④应用：基因工程中DNA末端补平、标记探针等（应用）。", "kps": "①定义(2分)②两种活性(1分)③小片段(1分)④应用(1分)", "kp": "dna_s1_3"}, {"id": "dna_term_10", "modI": 1, "term": "引物合成酶(Primase/DnaG)", "def": "①催化合成RNA引物的酶（定义）。②不需3'-OH即可从头合成(与DNA聚合酶不同)（特点）。③原核为DnaG蛋白，与DnaB(解螺旋酶)组成引发体(primosome)（组成）。④引物是DNA合成的起始点(提供3'-OH)（功能）。", "kps": "①定义(2分)②不需3'-OH(1分)③引发体(1分)④功能(1分)", "kp": "dna_s1_9"}, {"id": "dna_term_11", "modI": 1, "term": "DNA拓扑异构酶(Topoisomerase)", "def": "①通过切断和重新连接DNA链来改变DNA拓扑状态(超螺旋)的酶（定义）。②拓扑异构酶Ⅰ(ω蛋白)：切断一条链，消除负超螺旋，不需ATP（作用）。③拓扑异构酶Ⅱ(旋转酶gyrase)：切断两条链，引入负超螺旋，消除复制叉前进的扭曲张力，需ATP（作用）。④拓扑异构酶Ⅳ：分开环状DNA复制后形成的连锁染色体（作用）。", "kps": "①定义(2分)②Ⅰ消除负超螺旋(1分)③Ⅱ引入负超螺旋需ATP(1分)④Ⅳ分开连锁染色体(1分)", "kp": "dna_s1_10"}, {"id": "dna_term_12", "modI": 1, "term": "DNA解螺旋酶(Helicase/DnaB)", "def": "①利用ATP水解能量解开DNA双链的酶（定义）。②原核复制中的解螺旋酶为DnaB(6亚基,Mr 300000)，沿模板链5'→3'移动（组成）。③每解开一对碱基消耗2ATP（能耗）。④解螺旋酶Ⅰ/Ⅱ/Ⅲ沿5'→3'，Rep蛋白沿3'→5'(参与修复)（其他）。", "kps": "①定义(2分)②DnaB/5'→3'(1分)③2ATP/碱基对(1分)④其他类型(1分)", "kp": "dna_s1_11"}, {"id": "dna_term_13", "modI": 1, "term": "单链结合蛋白(SSB)", "def": "①结合于DNA单链上、防止单链重新互补配对的蛋白质（定义）。②Mr 75600，由4个亚基组成（结构）。③作用：稳定解开的单链模板状态，保护单链不被核酸酶降解（功能）。④是复制体/修复复合物的重要组成部分（意义）。", "kps": "①定义(2分)②4亚基(1分)③稳定单链/防降解(1分)④意义(1分)", "kp": "dna_s1_12"}, {"id": "dna_term_14", "modI": 1, "term": "复制体(Replisome)", "def": "①在DNA复制叉上分布的各种与复制有关的酶和蛋白质因子构成的复合物（定义）。②组成：旋转酶、解螺旋酶、引物合成酶、PolⅢ(β夹子)、PolⅠ、DNA连接酶、SSB等（组成）。③协同完成DNA双链的解旋、引物合成、链延伸、引物切除和连接（功能）。", "kps": "①定义(2分)②组成(2分)③功能(1分)", "kp": "dna_s1_13"}, {"id": "dna_term_15", "modI": 2, "term": "端粒(Telomere)", "def": "①真核生物线性染色体末端的特殊结构，由许多成串短的重复顺序组成（定义）。②通式5'(TxGy)n/3'(AxCy)n，人端粒重复序列TTAGGG（结构）。③功能：稳定染色体末端结构，防止端端融合和末端降解，解决末端复制问题（功能）。④端粒长度随细胞分裂缩短，与衰老相关（意义）。", "kps": "①定义(2分)②TTAGGG(1分)③功能(1分)④衰老(1分)", "kp": "dna_s2_9"}, {"id": "dna_term_16", "modI": 2, "term": "端粒酶(Telomerase)", "def": "①含RNA链的逆转录酶，以所含RNA为模板合成DNA端粒结构（定义）。②由蛋白质(逆转录酶催化亚基)+RNA链(~150碱基,含1.5拷贝端粒重复单位)组成（组成）。③催化端粒3'末端富G链延伸，解决线性DNA末端复制问题（功能）。④活性：生殖细胞/干细胞有活性，正常体细胞被抑制，肿瘤细胞被重新激活（分布）。", "kps": "①定义(2分)②蛋白+RNA(1分)③功能(1分)④活性分布(1分)", "kp": "dna_s2_11"}, {"id": "dna_term_17", "modI": 3, "term": "嘧啶二聚体(Pyrimidine Dimer)", "def": "①紫外线照射使DNA同一条链上相邻嘧啶碱基(TT/CT/CC)共价连接形成的二聚体（定义）。②结构：相邻嘧啶间形成环丁烷环状结构（结构）。③危害：使DNA双螺旋局部扭曲，阻碍DNA复制和转录（危害）。④修复：光复活酶直接分解(直接修复)或核苷酸切除修复(NER)（修复）。", "kps": "①定义(2分)②环丁烷结构(1分)③危害(1分)④修复(1分)", "kp": "dna_s3_1"}, {"id": "dna_term_18", "modI": 3, "term": "错配修复(Mismatch Repair, MMR)", "def": "①修复DNA复制后遗留的错配碱基的修复系统（定义）。②原理：复制后短时间内GATC序列半甲基化(模板链甲基化、新链未甲基化)→据此区分新旧链（原理）。③含错配碱基的未甲基化新链被切除，以甲基化链为模板修复（过程）。④关键蛋白：Dam(甲基化)、MutS(识别错配)、MutL、MutH(内切酶)（酶）。", "kps": "①定义(2分)②半甲基化区分新旧链(2分)③MutS等(1分)", "kp": "dna_s3_4"}, {"id": "dna_term_19", "modI": 3, "term": "直接修复(Direct Repair)", "def": "①直接将受损碱基恢复为正常碱基、不需切除的修复方式（定义）。②代表：光复活修复——可见光激活光复活酶分解嘧啶二聚体，恢复DNA正常结构（代表）。③从低等生物到鸟类皆有，植物中较重要（分布）。④与切除修复(需切除受损部分)不同（区别）。", "kps": "①定义(2分)②光复活酶(2分)③与切除修复区别(1分)", "kp": "dna_s3_5"}, {"id": "dna_term_20", "modI": 3, "term": "碱基切除修复(Base-Excision Repair, BER)", "def": "①切除受损的单个碱基、以完整链为模板修复的修复方式（定义）。②步骤：DNA糖苷酶断裂N-糖苷键除去异常碱基→AP位点→AP核酸内切酶切开→外切酶切除→PolⅠ填补→连接酶连接（过程）。③修复对象：单个异常碱基(脱氨基、氧化、烷化碱基等)（对象）。", "kps": "①定义(2分)②DNA糖苷酶+AP内切酶(2分)③修复对象(1分)", "kp": "dna_s3_7"}, {"id": "dna_term_21", "modI": 3, "term": "核苷酸切除修复(Nucleotide-Excision Repair, NER)", "def": "①切除含损伤部位的一段核苷酸、以完整链为模板修复的修复方式（定义）。②E.coli由ABC切除酶(UvrA/UvrB/UvrC)在损伤两侧同时切开(3'侧第5、5'侧第8个磷酸二酯键)，切除片段→PolⅠ填补→连接酶连接（过程）。③修复对象：引起DNA结构扭曲的大块损伤(嘧啶二聚体、交联)（对象）。④缺陷→着色性干皮病(XP)（临床）。", "kps": "①定义(2分)②UvrABC(1分)③修复对象(1分)④XP(1分)", "kp": "dna_s3_8"}, {"id": "dna_term_22", "modI": 3, "term": "着色性干皮病(Xeroderma Pigmentosum, XP)", "def": "①核苷酸切除修复(NER)系统缺陷导致的常染色体隐性遗传病（定义）。②机制：NER缺陷→不能修复紫外线引起的嘧啶二聚体→DNA损伤积累→突变（机制）。③症状：皮肤对紫外线极度敏感、色素沉着、易发皮肤癌（症状）。④意义：XP是证明NER和DNA修复重要性的经典疾病（意义）。", "kps": "①定义(2分)②NER缺陷机制(1分)③症状(1分)④意义(1分)", "kp": "dna_s3_9"}, {"id": "dna_term_23", "modI": 3, "term": "重组修复(Recombination Repair)", "def": "①通过遗传重组从完整母链补充子链缺口的修复方式（定义）。②过程：含嘧啶二聚体等损伤的DNA复制时，子代链在损伤部位出现缺口→RecA交换链从完整母链将相应片段移至子链缺口（过程）。③关键蛋白：RecA(交换链)、RecBCD(解旋/核酸酶/ATP酶)、RuvABC(分支迁移/拆分)（酶）。", "kps": "①定义(2分)②RecA交换链(2分)③RecBCD/RuvABC(1分)", "kp": "dna_s3_10"}, {"id": "dna_term_24", "modI": 3, "term": "SOS反应(SOS Response)", "def": "①许多可造成DNA损伤或抑制复制的处理引起的一系列复杂诱导反应(应急反应)（定义）。②机制：DNA损伤→ssDNA→结合RecA激活RecA*→促进LexA阻遏物自身分解→诱导修复基因(uvrABC/recA/umuDC等)表达（机制）。③包括DNA损伤修复、诱变效应、细胞分裂抑制（内容）。④意义：修复DNA+导致变异(进化意义)，是保命优先的应急修复（意义）。", "kps": "①定义(2分)②RecA-LexA机制(2分)③意义(1分)", "kp": "dna_s3_11"}, {"id": "dna_term_25", "modI": 3, "term": "RecA蛋白", "def": "①参与同源重组和SOS反应的关键蛋白质（定义）。②重组修复中起交换链作用(促进链交换/分支迁移)（重组功能）。③SOS反应中：结合ssDNA→激活RecA*(辅蛋白酶)→促进LexA分解→诱导修复基因（SOS功能）。④是DNA重组和损伤应答的核心蛋白（意义）。", "kps": "①定义(2分)②交换链(1分)③SOS激活LexA分解(1分)④意义(1分)", "kp": "dna_s3_13"}, {"id": "dna_term_26", "modI": 2, "term": "PCNA(增殖细胞抗原)", "def": "①真核生物DNA复制的滑动夹子(进行性因子)（定义）。②三聚体结构，相当于原核生物的β夹子（结构）。③功能：环绕DNA，使Polδ/Polε持续合成(提高持续合成能力)（功能）。④由RF-C(夹子装载器)装载到DNA上（装载）。", "kps": "①定义(2分)②三聚体=β夹子(1分)③提高持续合成(1分)④RF-C装载(1分)", "kp": "dna_s2_5"}, {"id": "dna_term_27", "modI": 3, "term": "跨损伤DNA合成(Translesion DNA Synthesis, TLS)", "def": "①DNA聚合酶越过模板上损伤位点继续进行DNA合成的过程（定义）。②当模板含嘧啶二聚体等损伤时，正常PolⅢ不能越过→由倾错DNA聚合酶(PolⅣ/Ⅴ)跨过损伤继续合成（机制）。③代价：倾错聚合酶易引入错误→易错修复(error-prone)（特点）。④属于SOS反应诱导的修复系统（归属）。", "kps": "①定义(2分)②PolⅣ/Ⅴ跨损伤(1分)③易错(1分)④属SOS(1分)", "kp": "dna_s3_12"}], "preview": null, "appcards": []};